import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import './index.css';
import Menu from './components/Menu';
import Hud, { Toast } from './components/Hud';
import { PauseMenu, Results } from './components/Overlays';
import { Game, HudState, RunResult } from './game/engine';
import { diffById, loadSave, SaveData, storeSave, trackById, TOTAL_LAPS } from './game/config';
import { sound } from './game/audio';

type Screen = 'menu' | 'play' | 'pause' | 'over';

const EMPTY_HUD: HudState = {
  score: 0, chain: 0, mult: 1, x2: 0, angle: 0, drifting: false, comboT: 0, kmh: 0, speedN: 0,
  lap: 1, laps: TOTAL_LAPS, timeLeft: 0, lapTime: 0, bestLap: Infinity, nitro: 0.5, boosting: false, wrong: false,
};

export default function App() {
  const hostRef = useRef<HTMLDivElement>(null), gameRef = useRef<Game | null>(null);
  const [screen, setScreen] = useState<Screen>('menu'), screenRef = useRef<Screen>('menu');
  const [hud, setHud] = useState<HudState>(EMPTY_HUD);
  const [save, setSave] = useState<SaveData>(() => loadSave()), saveRef = useRef(save);
  const [result, setResult] = useState<{ r: RunResult; record: boolean; prevBest: number } | null>(null);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [muted, setMuted] = useState(false);
  const [touch] = useState(() => typeof window !== 'undefined' && (window.matchMedia?.('(pointer: coarse)').matches ?? false));
  const timers = useRef<number[]>([]), toastId = useRef(0);

  const go = (s: Screen) => { screenRef.current = s; setScreen(s); };
  const persist = (s: SaveData) => { saveRef.current = s; setSave(s); storeSave(s); };

  useEffect(() => {
    const host = hostRef.current; if (!host) return;
    const game = new Game(host, {
      onHud: h => setHud(h),
      onEvent: (text, color, big) => {
        const id = ++toastId.current;
        setToasts(t => [...t.slice(-2), { id, text, color, big }]);
        timers.current.push(window.setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 1600));
      },
      onOver: r => {
        const prev = saveRef.current, tid = prev.track, prevBest = prev.best[tid] ?? 0;
        const record = r.score > prevBest;
        persist({
          ...prev, runs: prev.runs + 1,
          best: { ...prev.best, [tid]: Math.max(prevBest, r.score) },
          bestLap: isFinite(r.bestLap) ? { ...prev.bestLap, [tid]: Math.min(prev.bestLap[tid] ?? Infinity, r.bestLap) } : prev.bestLap,
        });
        setResult({ r, record, prevBest }); go('over');
        if (record || r.finished) {
          try { confetti({ particleCount: 150, spread: 100, origin: { y: 0.35 }, colors: ['#ff2a6d', '#05d9e8', '#ffd23f', '#ffffff'] }); } catch { /* sin confeti */ }
        }
      },
    });
    game.toAttract(trackById(saveRef.current.track));
    gameRef.current = game;
    return () => {
      timers.current.forEach(t => window.clearTimeout(t)); timers.current = [];
      game.dispose(); gameRef.current = null; sound.dispose();
    };
  }, []);

  const start = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    sound.init();
    (document.activeElement as HTMLElement | null)?.blur?.();
    setToasts([]); setResult(null); setHud(EMPTY_HUD);
    g.newRace(trackById(saveRef.current.track), diffById(saveRef.current.diff));
    go('play');
  }, []);

  const toMenu = useCallback(() => {
    gameRef.current?.toAttract(trackById(saveRef.current.track)); setToasts([]); go('menu');
  }, []);

  const setPaused = useCallback((p: boolean) => {
    const g = gameRef.current; if (!g) return;
    g.setPaused(p); go(p ? 'pause' : 'play');
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code !== 'Escape' && e.code !== 'KeyP') return;
      if (screenRef.current === 'play') setPaused(true); else if (screenRef.current === 'pause') setPaused(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [setPaused]);

  const toggleMute = () => { sound.init(); sound.setMuted(!muted); setMuted(!muted); };
  const mapRef = useCallback((c: HTMLCanvasElement | null) => { gameRef.current?.attachMinimap(c); }, []);

  return (
    <div className="dk-root relative h-screen min-h-[420px] w-full overflow-hidden bg-[#07020f]">
      <div ref={hostRef} className="absolute inset-0" />
      <div className="dk-vignette absolute inset-0" />
      <div className="dk-scan absolute inset-0" />

      {screen === 'menu' && (
        <Menu save={save} muted={muted} onMute={toggleMute} onPlay={start}
          onTrack={id => { sound.click(); persist({ ...saveRef.current, track: id }); gameRef.current?.toAttract(trackById(id)); }}
          onDiff={id => { sound.click(); persist({ ...saveRef.current, diff: id }); }} />
      )}

      {(screen === 'play' || screen === 'pause') && gameRef.current && (
        <Hud hud={hud} toasts={toasts} muted={muted} touch={touch} pad={gameRef.current.input.virtual}
          mapRef={mapRef} onPause={() => setPaused(true)} onMute={toggleMute} />
      )}

      {screen === 'pause' && <PauseMenu onResume={() => setPaused(false)} onRestart={start} onMenu={toMenu} />}

      {screen === 'over' && result && (
        <Results r={result.r} record={result.record} trackName={trackById(save.track).name} best={result.prevBest}
          onRetry={start} onMenu={toMenu} />
      )}
    </div>
  );
}

import { ArrowDown, ArrowLeft, ArrowRight, ArrowUp, Pause, Volume2, VolumeX, Zap, Hand } from 'lucide-react';
import clsx from 'clsx';
import type { PointerEvent as RPointerEvent, ReactNode } from 'react';
import { fmtPts, fmtTime } from '../game/config';
import type { HudState } from '../game/engine';
import type { VirtualPad } from '../game/input';

export interface Toast { id: number; text: string; color: string; big?: boolean }

interface Props {
  hud: HudState; toasts: Toast[]; muted: boolean; touch: boolean; pad: VirtualPad;
  mapRef: (c: HTMLCanvasElement | null) => void; onPause: () => void; onMute: () => void;
}

function PadBtn({ k, pad, className, children }: { k: keyof VirtualPad; pad: VirtualPad; className?: string; children: ReactNode }) {
  const set = (v: boolean) => (e: RPointerEvent) => { e.preventDefault(); pad[k] = v; };
  return (
    <button onPointerDown={set(true)} onPointerUp={set(false)} onPointerLeave={set(false)} onPointerCancel={set(false)}
      className={clsx('flex select-none items-center justify-center rounded-2xl border border-white/25 bg-black/35 text-white backdrop-blur active:bg-white/25', className)}>
      {children}
    </button>
  );
}

function Speedo({ kmh, n, boosting }: { kmh: number; n: number; boosting: boolean }) {
  const r = 46, c = Math.PI * r * 1.5;
  return (
    <div className="relative h-[120px] w-[120px]">
      <svg viewBox="0 0 120 120" className="absolute inset-0 rotate-[135deg]">
        <circle cx="60" cy="60" r={r} fill="none" stroke="rgba(255,255,255,0.12)" strokeWidth="8" strokeDasharray={`${c} 999`} strokeLinecap="round" />
        <circle cx="60" cy="60" r={r} fill="none" stroke={boosting ? '#38e8ff' : n > 0.8 ? '#ff2a6d' : '#ffb23d'} strokeWidth="8"
          strokeDasharray={`${c * n} 999`} strokeLinecap="round" style={{ filter: 'drop-shadow(0 0 6px currentColor)' }} />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <div className="dk-num text-4xl leading-none">{kmh}</div>
        <div className="text-[10px] tracking-widest text-white/55">KM/H</div>
      </div>
    </div>
  );
}

export default function Hud({ hud, toasts, muted, touch, pad, mapRef, onPause, onMute }: Props) {
  const low = hud.timeLeft < 10;
  return (
    <div className="pointer-events-none absolute inset-0">
      {/* Puntos y tiempo */}
      <div className="dk-glass absolute left-3 top-3 px-4 py-2.5">
        <div className="text-[10px] tracking-[0.3em] text-white/55">PUNTOS</div>
        <div className="dk-num dk-glow-pink text-3xl leading-none">{fmtPts(hud.score)}</div>
        <div className="mt-2 text-[10px] tracking-[0.3em] text-white/55">TIEMPO</div>
        <div className={clsx('dk-num text-2xl leading-none', low ? 'dk-blink text-[#ff3b5c]' : 'dk-glow-cyan')}>{hud.timeLeft.toFixed(1)}s</div>
      </div>

      {/* Vuelta + minimapa */}
      <div className="dk-glass absolute right-3 top-3 flex flex-col items-end gap-1 px-3 py-2.5">
        <div className="flex items-center gap-2">
          <button onClick={onMute} className="pointer-events-auto rounded-lg bg-white/10 p-1.5">{muted ? <VolumeX size={15} /> : <Volume2 size={15} />}</button>
          <button onClick={onPause} className="pointer-events-auto rounded-lg bg-white/10 p-1.5"><Pause size={15} /></button>
          <div className="dk-num ml-1 text-2xl leading-none">VUELTA {hud.lap}<span className="text-base text-white/50">/{hud.laps}</span></div>
        </div>
        <div className="text-[11px] text-white/65">Vuelta {fmtTime(hud.lapTime)} · Mejor {fmtTime(hud.bestLap)}</div>
        <canvas ref={mapRef} width={150} height={110} className="hidden sm:block" />
      </div>

      {/* Combo de derrape */}
      {hud.chain > 0 && (
        <div className="absolute left-1/2 top-4 -translate-x-1/2 text-center">
          <div className={clsx('dk-num dk-glow-gold text-5xl leading-none sm:text-6xl', hud.drifting && 'dk-pulse')}>{fmtPts(hud.chain)}</div>
          <div className="mt-1 flex items-center justify-center gap-2">
            <span className="dk-display rounded bg-[#ff2a6d] px-2 py-0.5 text-lg leading-none text-white shadow-[0_0_14px_#ff2a6d]">×{hud.mult}</span>
            {hud.x2 > 0 && <span className="dk-display rounded bg-[#ff3df0] px-2 py-0.5 text-lg leading-none">×2</span>}
            <span className="dk-display text-sm text-white/80">DRIFT</span>
          </div>
          <div className="mx-auto mt-1.5 h-1.5 w-48 overflow-hidden rounded-full bg-white/15">
            <div className="h-full bg-gradient-to-r from-[#05d9e8] via-[#ff2a6d] to-[#ffd23f]" style={{ width: `${hud.angle * 100}%` }} />
          </div>
          <div className="mx-auto mt-1 h-1 w-48 overflow-hidden rounded-full bg-white/10">
            <div className="h-full bg-white/70" style={{ width: `${hud.mult >= 5 ? 100 : hud.comboT * 100}%` }} />
          </div>
        </div>
      )}

      {hud.wrong && <div className="dk-display dk-blink absolute left-1/2 top-[38%] -translate-x-1/2 text-3xl text-[#ff3b5c]">¡Sentido contrario!</div>}

      {/* Avisos */}
      <div className="absolute left-1/2 top-[26%] flex -translate-x-1/2 flex-col items-center gap-1">
        {toasts.map(t => (
          <div key={t.id} className={clsx('dk-toast dk-display whitespace-nowrap', t.big ? 'text-4xl' : 'text-2xl')}
            style={{ color: t.color, textShadow: `0 0 14px ${t.color}, 2px 2px 0 #000` }}>{t.text}</div>
        ))}
      </div>

      {/* Velocímetro + nitro */}
      <div className={clsx('absolute flex items-end gap-2', touch ? 'bottom-36 right-3' : 'bottom-3 right-3')}>
        <div className="dk-glass flex flex-col items-center gap-1 px-2 py-2">
          <Zap size={14} className={hud.boosting ? 'text-[#38e8ff]' : 'text-white/60'} />
          <div className="relative h-20 w-2.5 overflow-hidden rounded-full bg-white/15">
            <div className="absolute bottom-0 w-full rounded-full bg-[#38e8ff] shadow-[0_0_10px_#38e8ff]" style={{ height: `${hud.nitro * 100}%` }} />
          </div>
        </div>
        <div className="dk-glass p-1"><Speedo kmh={hud.kmh} n={hud.speedN} boosting={hud.boosting} /></div>
      </div>

      {touch && (
        <>
          <div className="pointer-events-auto absolute bottom-4 left-4 flex gap-3">
            <PadBtn k="left" pad={pad} className="h-20 w-20"><ArrowLeft size={34} /></PadBtn>
            <PadBtn k="right" pad={pad} className="h-20 w-20"><ArrowRight size={34} /></PadBtn>
          </div>
          <div className="pointer-events-auto absolute bottom-4 right-4 grid grid-cols-3 gap-2">
            <PadBtn k="nitro" pad={pad} className="h-14 w-14 text-[#38e8ff]"><Zap size={24} /></PadBtn>
            <PadBtn k="brake" pad={pad} className="h-14 w-14 text-[#ffd23f]"><Hand size={24} /></PadBtn>
            <PadBtn k="up" pad={pad} className="row-span-2 h-[120px] w-16 bg-[#ff2a6d]/40"><ArrowUp size={30} /></PadBtn>
            <PadBtn k="down" pad={pad} className="col-span-2 h-14"><ArrowDown size={24} /></PadBtn>
          </div>
        </>
      )}
    </div>
  );
}

import { Flame, Gauge, Play, Trophy, Volume2, VolumeX } from 'lucide-react';
import clsx from 'clsx';
import { DIFFS, fmtPts, fmtTime, SaveData, TRACKS } from '../game/config';

interface Props {
  save: SaveData; muted: boolean;
  onMute: () => void; onPlay: () => void; onTrack: (id: string) => void; onDiff: (id: string) => void;
}

const CONTROLS: Array<[string, string]> = [
  ['↑ / W', 'Acelerar'], ['↓ / S', 'Frenar · marcha atrás'], ['← → / A D', 'Girar y contravolante'],
  ['Espacio', 'Freno de mano (iniciar derrape)'], ['Shift / N', 'Nitro'], ['Esc / P', 'Pausa'],
];

export default function Menu({ save, muted, onMute, onPlay, onTrack, onDiff }: Props) {
  const total = Object.values(save.best).reduce((a, b) => a + b, 0);
  return (
    <div className="absolute inset-0 flex flex-col overflow-y-auto bg-gradient-to-r from-[#07020fee] via-[#07020f99] to-transparent">
      <button onClick={onMute} className="dk-chip absolute right-4 top-4 z-10 p-2.5" aria-label="Silenciar">
        {muted ? <VolumeX size={18} /> : <Volume2 size={18} />}
      </button>
      <div className="dk-in flex w-full max-w-[560px] flex-col gap-4 p-5 sm:p-8">
        <div>
          <div className="dk-display text-xs tracking-[0.4em] text-[#6ff3ff]">Midnight touge series</div>
          <h1 className="dk-title mt-1 text-6xl sm:text-7xl">DRIFT</h1>
          <h1 className="dk-title dk-title-cyan -mt-1 text-6xl sm:text-7xl">KINGS</h1>
          <p className="mt-3 max-w-md text-sm text-white/75">
            Cruza la noche de lado. Encadena derrapes para subir el multiplicador, roza el tráfico, clava los puntos de clip
            y termina las 3 vueltas antes de que se agote el tiempo.
          </p>
        </div>

        <div className="dk-glass p-3">
          <div className="dk-display mb-2 flex items-center gap-2 text-xs text-white/60"><Flame size={14} /> Pista</div>
          <div className="grid grid-cols-1 gap-2 sm:grid-cols-3">
            {TRACKS.map(t => (
              <button key={t.id} onClick={() => onTrack(t.id)}
                className={clsx('dk-chip p-2.5 text-left', save.track === t.id && 'dk-chip-on')}>
                <div className="h-1.5 w-full rounded-full" style={{ background: `linear-gradient(90deg, ${t.neon[0]}, ${t.neon[1]}, ${t.neon[2]})` }} />
                <div className="dk-display mt-2 text-base leading-tight">{t.name}</div>
                <div className="text-[11px] text-white/55">{t.sub}</div>
                <div className="mt-1 flex items-center gap-1 text-[11px] text-[#ffe066]"><Trophy size={11} /> {save.best[t.id] ? fmtPts(save.best[t.id]) : '—'}</div>
              </button>
            ))}
          </div>
          <p className="mt-2 text-xs text-white/60">{TRACKS.find(t => t.id === save.track)?.desc}</p>
        </div>

        <div className="dk-glass p-3">
          <div className="dk-display mb-2 flex items-center gap-2 text-xs text-white/60"><Gauge size={14} /> Dificultad</div>
          <div className="grid grid-cols-3 gap-2">
            {DIFFS.map(d => (
              <button key={d.id} onClick={() => onDiff(d.id)} className={clsx('dk-chip px-2 py-2 text-center', save.diff === d.id && 'dk-chip-on')}>
                <div className="dk-display text-sm">{d.name}</div>
                <div className="text-[10px] leading-tight text-white/55">{d.desc}</div>
              </button>
            ))}
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-4">
          <button onClick={onPlay} className="dk-btn flex items-center gap-2 px-10 py-3.5 text-2xl">
            <Play size={22} fill="currentColor" /> Jugar
          </button>
          <div className="text-xs text-white/65">
            <div>Récord pista: <span className="dk-num dk-glow-gold text-base">{save.best[save.track] ? fmtPts(save.best[save.track]) : '—'}</span></div>
            <div>Mejor vuelta: <span className="dk-num text-sm">{fmtTime(save.bestLap[save.track] ?? 0)}</span> · Total: {fmtPts(total)}</div>
          </div>
        </div>

        <div className="dk-glass grid grid-cols-2 gap-x-4 gap-y-1 p-3 text-[11px]">
          {CONTROLS.map(([k, v]) => (
            <div key={k} className="flex items-center gap-2">
              <span className="dk-num rounded bg-white/10 px-1.5 py-0.5 text-[#6ff3ff]">{k}</span>
              <span className="text-white/70">{v}</span>
            </div>
          ))}
          <div className="col-span-2 mt-1 text-white/45">En móvil: botones en pantalla para girar, gas, freno, freno de mano y nitro.</div>
        </div>
      </div>
    </div>
  );
}

import { Home, Play, RotateCcw, Trophy } from 'lucide-react';
import { fmtPts, fmtTime } from '../game/config';
import type { RunResult } from '../game/engine';

export function PauseMenu({ onResume, onRestart, onMenu }: { onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <div className="absolute inset-0 flex items-center justify-center bg-[#07020f]/70 backdrop-blur-sm">
      <div className="dk-glass dk-in flex w-72 flex-col gap-3 p-6 text-center">
        <h2 className="dk-title text-5xl">PAUSA</h2>
        <button onClick={onResume} className="dk-btn flex items-center justify-center gap-2 py-3 text-xl"><Play size={18} fill="currentColor" /> Continuar</button>
        <button onClick={onRestart} className="dk-btn-ghost flex items-center justify-center gap-2 py-2.5"><RotateCcw size={16} /> Reiniciar</button>
        <button onClick={onMenu} className="dk-btn-ghost flex items-center justify-center gap-2 py-2.5"><Home size={16} /> Menú</button>
        <p className="text-xs text-white/50">Esc o P para continuar</p>
      </div>
    </div>
  );
}

interface ResultsProps { r: RunResult; record: boolean; trackName: string; best: number; onRetry: () => void; onMenu: () => void }

export function Results({ r, record, trackName, best, onRetry, onMenu }: ResultsProps) {
  const rows: Array<[string, string]> = [
    ['Vueltas completadas', `${r.laps} / 3`], ['Mejor vuelta', fmtTime(r.bestLap)], ['Mejor combo', fmtPts(r.maxChain)],
    ['Clips', String(r.clips)], ['Rozones', String(r.nears)], ['Bonus de tiempo', r.timeBonus ? `+${fmtPts(r.timeBonus)}` : '—'],
  ];
  return (
    <div className="absolute inset-0 flex items-center justify-center bg-gradient-to-t from-[#07020f]/90 to-[#07020f]/40 p-4">
      <div className="dk-glass dk-in w-full max-w-md p-6 text-center">
        <div className="dk-display text-xs tracking-[0.35em] text-[#6ff3ff]">{trackName}</div>
        <h2 className={r.finished ? 'dk-title dk-title-cyan mt-1 text-5xl' : 'dk-title mt-1 text-5xl'}>{r.finished ? '¡META!' : 'SIN TIEMPO'}</h2>
        {record && <div className="dk-display dk-pulse mt-2 inline-flex items-center gap-2 rounded-full bg-[#ffd23f] px-3 py-1 text-sm text-[#1a0a2a]"><Trophy size={14} /> ¡Nuevo récord!</div>}
        <div className="dk-num dk-glow-gold mt-3 text-6xl leading-none">{fmtPts(r.score)}</div>
        <div className="text-xs text-white/55">puntos · récord {fmtPts(Math.max(best, r.score))}</div>
        <div className="mt-4 grid grid-cols-2 gap-2 text-left text-sm">
          {rows.map(([k, v]) => (
            <div key={k} className="dk-chip px-3 py-1.5"><div className="text-[10px] uppercase tracking-wider text-white/50">{k}</div><div className="dk-num text-lg">{v}</div></div>
          ))}
        </div>
        <div className="mt-5 flex justify-center gap-3">
          <button onClick={onRetry} className="dk-btn flex items-center gap-2 px-6 py-3 text-xl"><RotateCcw size={18} /> Reintentar</button>
          <button onClick={onMenu} className="dk-btn-ghost flex items-center gap-2 px-5 py-3"><Home size={16} /> Menú</button>
        </div>
      </div>
    </div>
  );
}

// Audio procedural con Web Audio: motor, chirrido de neumáticos, efectos y un bajo synthwave.
class Sound {
  private ctx: AudioContext | null = null;
  private master!: GainNode;
  private engGain!: GainNode; private eng1!: OscillatorNode; private eng2!: OscillatorNode; private engF!: BiquadFilterNode;
  private sqGain!: GainNode; private sqF!: BiquadFilterNode;
  private musGain!: GainNode;
  private muted = false;
  private step = 0; private timer = 0;

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AC) return;
    const c = (this.ctx = new AC());
    this.master = c.createGain(); this.master.gain.value = this.muted ? 0 : 0.6; this.master.connect(c.destination);
    // Motor
    this.engF = c.createBiquadFilter(); this.engF.type = 'lowpass'; this.engF.frequency.value = 600;
    this.engGain = c.createGain(); this.engGain.gain.value = 0;
    this.eng1 = c.createOscillator(); this.eng1.type = 'sawtooth';
    this.eng2 = c.createOscillator(); this.eng2.type = 'square';
    this.eng1.connect(this.engF); this.eng2.connect(this.engF); this.engF.connect(this.engGain); this.engGain.connect(this.master);
    this.eng1.start(); this.eng2.start();
    // Neumáticos: ruido filtrado
    const buf = c.createBuffer(1, c.sampleRate, c.sampleRate), d = buf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    const noise = c.createBufferSource(); noise.buffer = buf; noise.loop = true;
    this.sqF = c.createBiquadFilter(); this.sqF.type = 'bandpass'; this.sqF.frequency.value = 1400; this.sqF.Q.value = 6;
    this.sqGain = c.createGain(); this.sqGain.gain.value = 0;
    noise.connect(this.sqF); this.sqF.connect(this.sqGain); this.sqGain.connect(this.master); noise.start();
    this.musGain = c.createGain(); this.musGain.gain.value = 0.11; this.musGain.connect(this.master);
    this.timer = window.setInterval(() => this.tick(), 150);
  }

  /** Bajo arpegiado en La menor (synthwave nocturno). */
  private tick() {
    const c = this.ctx; if (!c || this.muted) return;
    const roots = [45, 45, 41, 43], seq = [0, 12, 7, 12, 0, 12, 10, 7];
    const note = roots[Math.floor(this.step / 16) % 4] + seq[this.step % 8];
    this.blip(440 * Math.pow(2, (note - 69) / 12), 0.14, 'sawtooth', 0.9, this.musGain, 900);
    if (this.step % 4 === 0) this.blip(55, 0.18, 'sine', 1.4, this.musGain);
    this.step++;
  }

  private blip(freq: number, dur: number, type: OscillatorType, vol: number, dest?: AudioNode, lp = 0, slide = 0) {
    const c = this.ctx; if (!c) return;
    const t = c.currentTime, o = c.createOscillator(), g = c.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq * slide), t + dur);
    g.gain.setValueAtTime(vol * 0.3, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    let node: AudioNode = o;
    if (lp) { const f = c.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = lp; o.connect(f); node = f; }
    node.connect(g); g.connect(dest ?? this.master); o.start(t); o.stop(t + dur + 0.02);
  }

  private noiseHit(dur: number, vol: number, freq: number) {
    const c = this.ctx; if (!c) return;
    const t = c.currentTime, b = c.createBuffer(1, Math.floor(c.sampleRate * dur), c.sampleRate), d = b.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / d.length);
    const s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain();
    s.buffer = b; f.type = 'lowpass'; f.frequency.value = freq; g.gain.value = vol;
    s.connect(f); f.connect(g); g.connect(this.master); s.start(t);
  }

  /** rpm 0..1, carga 0..1, derrape 0..1 */
  engine(rpm: number, load: number, squeal: number) {
    const c = this.ctx; if (!c) return;
    const t = c.currentTime, f = 48 + rpm * 150;
    this.eng1.frequency.setTargetAtTime(f, t, 0.05); this.eng2.frequency.setTargetAtTime(f * 0.501, t, 0.05);
    this.engF.frequency.setTargetAtTime(400 + load * 1600 + rpm * 600, t, 0.08);
    this.engGain.gain.setTargetAtTime(0.06 + load * 0.08, t, 0.1);
    this.sqGain.gain.setTargetAtTime(squeal * 0.22, t, 0.06);
    this.sqF.frequency.setTargetAtTime(1100 + squeal * 700, t, 0.1);
  }
  silence() { const c = this.ctx; if (!c) return; this.engGain.gain.setTargetAtTime(0, c.currentTime, 0.1); this.sqGain.gain.setTargetAtTime(0, c.currentTime, 0.05); }

  click() { this.blip(880, 0.06, 'square', 0.5); }
  pickup() { [660, 990, 1320].forEach((f, i) => window.setTimeout(() => this.blip(f, 0.12, 'triangle', 0.8), i * 50)); }
  clip() { this.blip(1200, 0.25, 'sine', 0.9, undefined, 0, 1.8); }
  bank(big: boolean) { (big ? [523, 659, 784, 1046] : [523, 784]).forEach((f, i) => window.setTimeout(() => this.blip(f, 0.18, 'square', 0.5, undefined, 3000), i * 70)); }
  crash() { this.noiseHit(0.4, 0.9, 900); this.blip(90, 0.3, 'sawtooth', 0.8, undefined, 0, 0.4); }
  cone() { this.noiseHit(0.12, 0.5, 2500); this.blip(300, 0.1, 'square', 0.4); }
  lost() { this.blip(330, 0.35, 'sawtooth', 0.6, undefined, 1200, 0.5); }
  beep(go: boolean) { this.blip(go ? 1046 : 523, go ? 0.4 : 0.15, 'square', 0.6); }
  lap() { [784, 988, 1175, 1568].forEach((f, i) => window.setTimeout(() => this.blip(f, 0.16, 'triangle', 0.9), i * 90)); }
  over() { [523, 440, 349, 262].forEach((f, i) => window.setTimeout(() => this.blip(f, 0.3, 'triangle', 0.8), i * 160)); }

  setMuted(m: boolean) {
    this.muted = m;
    if (this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.6, this.ctx.currentTime, 0.05);
  }

  dispose() {
    window.clearInterval(this.timer);
    this.ctx?.close().catch(() => undefined); this.ctx = null;
  }
}

