import * as THREE from 'three';
import { lin, radialTexture } from './three-compat';
import type { Track } from './track';

export interface Controls { throttle: number; brake: number; steer: number; handbrake: boolean; nitro: boolean }

export interface CarMesh { root: THREE.Group; body: THREE.Group; wheels: THREE.Mesh[]; pivots: THREE.Group[]; brake: THREE.MeshBasicMaterial }

/** Coche JDM low-poly: carrocería baja, alerón, faros, neón bajo el chasis. */
export function buildCarMesh(paint: string, accent: string, glow = true): CarMesh {
  const root = new THREE.Group(), body = new THREE.Group();
  root.add(body);
  const paintMat = new THREE.MeshPhongMaterial({ color: lin(paint), specular: lin('#9a9ab8'), shininess: 90 });
  const dark = new THREE.MeshPhongMaterial({ color: lin('#0b0b12'), specular: lin('#556'), shininess: 120 });
  const accentMat = new THREE.MeshBasicMaterial({ color: lin(accent) });
  const box = (w: number, h: number, d: number, m: THREE.Material, x: number, y: number, z: number) => {
    const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m); b.position.set(x, y, z); body.add(b); return b;
  };
  box(1.9, 0.5, 4.4, paintMat, 0, 0.58, 0);
  box(1.84, 0.16, 1.5, paintMat, 0, 0.88, 1.35).rotation.x = 0.06;
  box(1.6, 0.46, 2.0, dark, 0, 1.06, -0.35);
  box(1.5, 0.06, 1.7, paintMat, 0, 1.31, -0.4);
  box(0.42, 0.03, 4.42, accentMat, 0.28, 0.84, 0);
  box(2.0, 0.2, 0.36, dark, 0, 0.36, 2.12);
  box(1.96, 0.08, 0.5, paintMat, 0, 1.28, -2.0);
  [-0.6, 0.6].forEach(x => box(0.08, 0.38, 0.12, dark, x, 1.05, -2.0));
  const head = new THREE.MeshBasicMaterial({ color: lin('#fff6dd') });
  [-0.62, 0.62].forEach(x => box(0.46, 0.12, 0.05, head, x, 0.66, 2.21));
  const brake = new THREE.MeshBasicMaterial({ color: lin('#c0102a') });
  [-0.66, 0.66].forEach(x => box(0.42, 0.13, 0.05, brake, x, 0.7, -2.21));
  const wheels: THREE.Mesh[] = [], pivots: THREE.Group[] = [];
  const wGeo = new THREE.CylinderGeometry(0.37, 0.37, 0.3, 14); wGeo.rotateZ(Math.PI / 2);
  const tire = new THREE.MeshLambertMaterial({ color: lin('#121216') });
  const rimGeo = new THREE.CylinderGeometry(0.24, 0.24, 0.31, 8); rimGeo.rotateZ(Math.PI / 2);
  const rimMat = new THREE.MeshPhongMaterial({ color: lin('#c9ccd6'), shininess: 100 });
  [[0.9, 1.35], [-0.9, 1.35], [0.9, -1.35], [-0.9, -1.35]].forEach(([x, z], i) => {
    const pivot = new THREE.Group(); pivot.position.set(x, 0.37, z); root.add(pivot);
    const w = new THREE.Mesh(wGeo, tire); w.add(new THREE.Mesh(rimGeo, rimMat)); pivot.add(w);
    wheels.push(w); if (i < 2) pivots.push(pivot);
  });
  if (glow) {
    const under = new THREE.Mesh(new THREE.PlaneGeometry(3.6, 6.2), new THREE.MeshBasicMaterial({
      map: radialTexture([[0, accent], [0.45, accent + '88'], [1, accent + '00']]), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    under.rotation.x = -Math.PI / 2; under.position.y = 0.04; root.add(under);
    const beam = new THREE.Mesh(new THREE.PlaneGeometry(7, 14), new THREE.MeshBasicMaterial({
      map: radialTexture([[0, 'rgba(255,240,210,0.55)'], [0.5, 'rgba(255,230,190,0.18)'], [1, 'rgba(255,230,190,0)']]),
      transparent: true, blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    beam.rotation.x = -Math.PI / 2; beam.position.set(0, 0.05, 8.5); root.add(beam);
  }
  return { root, body, wheels, pivots, brake };
}

/** Física arcade de derrape: velocidad libre en el mundo + agarre lateral variable. */
export class Car {
  pos = new THREE.Vector3();
  vel = new THREE.Vector3();
  heading = 0; yawRate = 0; steer = 0;
  drifting = false; slip = 0; speed = 0; vF = 0;
  nitro = 0.5; boosting = false; spun = false;
  private exitT = 0;
  grip = 1;
  readonly fwd = new THREE.Vector3(0, 0, 1);
  readonly rgt = new THREE.Vector3(-1, 0, 0);

  constructor(readonly mesh: CarMesh) {}

  place(p: THREE.Vector3, tangent: THREE.Vector3, speed: number) {
    this.pos.copy(p); this.heading = Math.atan2(tangent.x, tangent.z);
    this.vel.copy(tangent).multiplyScalar(speed); this.yawRate = 0; this.drifting = false; this.slip = 0; this.spun = false;
    this.sync(0);
  }

  update(dt: number, c: Controls) {
    const s = Math.sin(this.heading), co = Math.cos(this.heading);
    this.fwd.set(s, 0, co); this.rgt.set(-co, 0, s);
    let vF = this.vel.dot(this.fwd), vR = this.vel.dot(this.rgt);
    this.speed = Math.hypot(vF, vR);
    this.steer += (c.steer - this.steer) * Math.min(1, dt * 7);

    // Longitudinal
    this.boosting = c.nitro && this.nitro > 0 && c.throttle > 0;
    const top = this.boosting ? 52 : 43;
    if (c.throttle) vF += 17 * (1 - Math.max(0, vF) / top) * dt * (this.drifting ? 0.85 : 1);
    if (this.boosting) { vF += 13 * dt; this.nitro = Math.max(0, this.nitro - dt * 0.3); }
    if (c.brake) vF -= vF > 1 ? 28 * dt : 9 * dt;
    if (vF < -9) vF = -9;
    if (c.handbrake) vF -= Math.sign(vF) * 7 * dt;
    vF -= vF * 0.09 * dt + (c.throttle ? 0 : Math.sign(vF) * 1.2 * dt);

    // Estado de derrape
    this.slip = Math.atan2(vR, Math.max(Math.abs(vF), 1));
    if (!this.drifting && this.speed > 9 && ((c.handbrake && Math.abs(this.steer) > 0.2) || (Math.abs(this.steer) > 0.75 && this.speed > 21))) {
      this.drifting = true; this.exitT = 0;
      this.yawRate -= this.steer * 1.3; // patada inicial
    }
    if (this.drifting) {
      this.exitT = Math.abs(this.slip) < 0.1 && !c.handbrake ? this.exitT + dt : 0;
      if (this.exitT > 0.35 || this.speed < 5) this.drifting = false;
    }

    // Agarre lateral (en derrape la velocidad lateral se convierte en avance: mantiene el impulso)
    const g = this.drifting ? (c.handbrake ? 0.55 : 1.5) * this.grip : 7.5 * this.grip;
    const dv = vR * Math.min(1, g * dt);
    vR -= dv; vF += Math.abs(dv) * (this.drifting ? 0.5 : 0.15) * Math.sign(vF || 1);

    // Giro
    const sf = Math.min(1, this.speed / 8) * (vF < -0.5 ? -1 : 1);
    let target = -this.steer * (this.drifting ? 2.2 : 1.9 / (1 + this.speed * 0.018)) * sf;
    if (this.drifting) target += Math.max(-1.2, Math.min(1.2, this.slip)) * (0.5 + c.throttle * 1.5);
    this.yawRate += (target - this.yawRate) * Math.min(1, dt * (this.drifting ? 3.8 : 9));
    this.heading += this.yawRate * dt;

    // Trompo
    if (Math.abs(this.slip) > 1.45 && this.speed > 7) { this.spun = true; vF *= 0.5; vR *= 0.5; this.drifting = false; }

    this.vel.set(this.fwd.x * vF + this.rgt.x * vR, 0, this.fwd.z * vF + this.rgt.z * vR);
    this.vF = vF;
    this.pos.addScaledVector(this.vel, dt);
    this.sync(dt, c.brake > 0 || c.handbrake);
  }

  /** Lleva el estado físico a la malla (giro de ruedas, balanceo, luces de freno). */
  sync(dt: number, braking = false) {
    const m = this.mesh;
    m.root.position.copy(this.pos); m.root.rotation.y = this.heading;
    m.wheels.forEach(w => { w.rotation.x += (this.vF * dt) / 0.37; });
    const vis = this.drifting ? Math.max(-0.6, Math.min(0.6, this.slip * 0.9)) : -this.steer * 0.45;
    m.pivots.forEach(p => { p.rotation.y += (vis - p.rotation.y) * Math.min(1, dt * 12); });
    const roll = Math.max(-0.09, Math.min(0.09, this.yawRate * this.speed * 0.0035));
    m.body.rotation.z += (roll - m.body.rotation.z) * Math.min(1, dt * 6);
    m.brake.color.copy(lin(braking ? '#ff2a4a' : '#9a0c22'));
  }

  /** Posición de una rueda trasera en el mundo (side: -1 izq, 1 der). */
  rearWheel(side: number, out: THREE.Vector3) {
    return out.copy(this.pos).addScaledVector(this.fwd, -1.35).addScaledVector(this.rgt, side * 0.9);
  }
}

/** Piloto automático con derrapes (modo atracción del menú). */
export function autopilot(car: Car, track: Track, hint: number): Controls {
  const N = track.pts.length, ahead = Math.round((7 + car.speed * 0.45) / 2);
  const tgt = track.pts[(hint + ahead) % N];
  const want = Math.atan2(tgt.x - car.pos.x, tgt.z - car.pos.z);
  let err = want - car.heading; err = Math.atan2(Math.sin(err), Math.cos(err));
  let curv = 0; for (let k = 2; k < 14; k++) curv = Math.max(curv, Math.abs(track.curv[(hint + k) % N]));
  const corner = 16 + 6 / (curv + 0.02);
  return {
    throttle: car.speed < corner + 4 ? 1 : 0, brake: car.speed > corner + 10 ? 1 : 0,
    steer: Math.max(-1, Math.min(1, -err * 2.4)), handbrake: curv > 0.045 && car.speed > 17 && Math.abs(err) > 0.25, nitro: false,
  };
}

