export interface HudState {
  score: number; chain: number; mult: number; x2: number; angle: number; drifting: boolean; comboT: number;
  kmh: number; speedN: number; lap: number; laps: number; timeLeft: number; lapTime: number; bestLap: number;
  nitro: number; boosting: boolean; wrong: boolean;
}
export interface RunResult { score: number; finished: boolean; laps: number; bestLap: number; maxChain: number; clips: number; nears: number; timeBonus: number }
export interface GameCallbacks { onHud: (h: HudState) => void; onEvent: (text: string, color: string, big?: boolean) => void; onOver: (r: RunResult) => void }

type Mode = 'attract' | 'race' | 'over';
const RANKS: Array<[number, string, string]> = [[12000, '¡LEGENDARIO!', '#ffd23f'], [6000, '¡ÉPICO!', '#ff3df0'], [2500, '¡GENIAL!', '#38e8ff'], [0, 'BIEN', '#ffffff']];

export class Game {
  readonly input = new Input();
  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private camera = new THREE.PerspectiveCamera(62, 1, 0.3, 1500);
  private world: THREE.Group | null = null;
  private track!: Track; private scenery!: Scenery; private props!: Props; private car!: Car;
  private fx = new Fx();
  private mode: Mode = 'attract'; private paused = false;
  private diff: DiffDef = DIFFS[1];
  private raf = 0; private last = 0; private ro: ResizeObserver;
  private hint = 0; private t = 0; private hudT = 0; private shake = 0;
  private skidPrev: Array<THREE.Vector3 | null> = [null, null]; private emitAcc = 0;
  private minimap: HTMLCanvasElement | null = null; private mapPts: Array<[number, number]> = [];
  // Estado de la partida
  private score = 0; private chain = 0; private mult = 1; private chainT = 0; private idle = 0; private x2 = 0;
  private lap = 1; private nextCp = 1; private timeLeft = 0; private lapTime = 0; private bestLap = Infinity;
  private maxChain = 0; private clips = 0; private nears = 0; private wrong = false;
  private v = new THREE.Vector3(); private w = new THREE.Vector3(); private look = new THREE.Vector3();

  constructor(private host: HTMLElement, private cb: GameCallbacks) {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    setupRenderer(this.renderer);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.domElement.style.cssText = 'width:100%;height:100%;display:block';
    host.appendChild(this.renderer.domElement);
    this.scene.add(this.fx.group, this.camera);
    this.ro = new ResizeObserver(() => this.resize()); this.ro.observe(host); this.resize();
    this.last = performance.now();
    this.raf = requestAnimationFrame(this.frame);
  }

  private resize() {
    const w = Math.max(1, this.host.clientWidth), h = Math.max(1, this.host.clientHeight);
    this.renderer.setSize(w, h, false); this.camera.aspect = w / h; this.camera.updateProjectionMatrix();
  }

  private build(def: TrackDef, diff: DiffDef) {
    this.diff = diff;
    if (!this.world || this.track.def !== def) { // misma pista: se reutiliza el mundo (arranque instantáneo)
      if (this.world) { this.scene.remove(this.world); disposeTree(this.world); }
      this.world = new THREE.Group();
      this.track = new Track(def);
      this.scenery = new Scenery(this.track, this.scene);
      this.props = new Props(this.track, diff);
      this.car = new Car(buildCarMesh(PLAYER_COLOR, PLAYER_ACCENT));
      this.world.add(this.track.group, this.scenery.group, this.props.group, this.car.mesh.root);
      this.scene.add(this.world);
    }
    this.props.diff = diff; this.car.grip = diff.grip;
    this.fx.reset(); this.fx.setTint(def.kind === 'touge' ? '#d9cfe8' : def.kind === 'port' ? '#c9e4ee' : '#e6c9e4', PLAYER_ACCENT);
    this.mapPts = this.track.pts.map(p => [p.x, p.z]);
    const start = this.track.at(6, 0, new THREE.Vector3(), this.v);
    this.car.place(start, this.v, 21);
    this.hint = this.track.query(this.car.pos).idx;
    this.props.reset(1, 6);
    this.skidPrev = [null, null];
    this.camera.position.copy(start).add(new THREE.Vector3(-this.v.x * 10, 5, -this.v.z * 10));
  }

  toAttract(def: TrackDef) { this.build(def, DIFFS[1]); this.mode = 'attract'; this.paused = false; sound.silence(); }

  newRace(def: TrackDef, diff: DiffDef) {
    this.build(def, diff);
    this.input.reset();
    this.mode = 'race'; this.paused = false;
    this.score = 0; this.chain = 0; this.mult = 1; this.chainT = 0; this.idle = 0; this.x2 = 0;
    this.lap = 1; this.nextCp = 1; this.timeLeft = def.time * diff.time; this.lapTime = 0; this.bestLap = Infinity;
    this.maxChain = 0; this.clips = 0; this.nears = 0; this.car.nitro = 0.5;
    this.cb.onEvent('¡SALIDA LANZADA!', '#38e8ff', true); sound.beep(true);
  }

  setPaused(p: boolean) { this.paused = p; if (p) sound.silence(); }
  attachMinimap(c: HTMLCanvasElement | null) { this.minimap = c; }

  private frame = (now: number) => {
    this.raf = requestAnimationFrame(this.frame);
    const dt = Math.min(0.05, Math.max(0, (now - this.last) / 1000)); this.last = now;
    if (!this.paused) this.step(dt);
    this.renderer.render(this.scene, this.camera);
  };

  private breakCombo(text: string) {
    if (this.chain > 0) { this.cb.onEvent(text, '#ff3b5c'); sound.lost(); }
    this.chain = 0; this.mult = 1; this.chainT = 0; this.idle = 0;
  }

  private bank() {
    if (this.chain < 1) return;
    const pts = Math.round(this.chain), rank = RANKS.find(r => pts >= r[0])!;
    this.score += pts; this.maxChain = Math.max(this.maxChain, pts);
    this.cb.onEvent(`${rank[1]} +${pts.toLocaleString('es-ES')}`, rank[2], pts >= 2500); sound.bank(pts >= 2500);
    this.chain = 0; this.mult = 1; this.chainT = 0; this.idle = 0;
  }

  private step(dt: number) {
    this.t += dt;
    const car = this.car, tr = this.track, race = this.mode === 'race';
    const ctl: Controls = race
      ? { throttle: this.input.throttle, brake: this.input.brake, steer: this.input.steer, handbrake: this.input.handbrake, nitro: this.input.nitro }
      : autopilot(car, tr, this.hint);
    car.update(dt, ctl);

    // Muros
    const hit = tr.query(car.pos, this.hint); this.hint = hit.idx;
    const lim = tr.wallOff - 1.1;
    if (Math.abs(hit.lateral) > lim) {
      const s = Math.sign(hit.lateral);
      car.pos.addScaledVector(hit.right, -s * (Math.abs(hit.lateral) - lim));
      const vn = car.vel.dot(hit.right) * s;
      if (vn > 0) {
        car.vel.addScaledVector(hit.right, -s * vn * 1.3); car.vel.multiplyScalar(1 - Math.min(0.3, vn * 0.025));
        this.v.copy(car.pos).addScaledVector(hit.right, s * 1.1).setY(0.6);
        this.fx.burst(this.v, Math.min(26, 4 + Math.round(vn * 2)));
        if (vn > 6) { this.shake = Math.min(1, vn / 14); if (race) { sound.crash(); this.breakCombo('¡CONTRA EL MURO!'); } }
      }
    }

    // Vueltas y tiempo
    if (race) {
      const N = tr.pts.length;
      this.timeLeft -= dt; this.lapTime += dt; this.x2 = Math.max(0, this.x2 - dt);
      if (this.nextCp < 3 && hit.idx > (N * this.nextCp) / 3 && hit.idx < (N * this.nextCp) / 3 + 25) this.nextCp++;
      else if (this.nextCp === 3 && hit.idx < 20) this.completeLap();
      this.wrong = car.vel.dot(hit.tangent) < -4;
      if (this.timeLeft <= 0 && this.mode === 'race') this.finish(false);
    }

    // Puntuación de derrape
    if (race) {
      const angle = Math.abs(car.slip), active = car.drifting && car.speed > 8 && angle > 0.17;
      if (active) {
        this.chainT += dt; this.idle = 0;
        this.mult = Math.min(5, 1 + Math.floor(this.chainT / 2.2));
        this.chain += dt * car.speed * Math.min(angle, 1.1) * 14 * this.mult * (this.x2 > 0 ? 2 : 1);
      } else if (this.chain > 0 && (this.idle += dt) > 1.1) this.bank();
      if (car.spun) { car.spun = false; this.breakCombo('¡TROMPO!'); this.shake = 0.4; }
    } else car.spun = false;

    // Objetos
    const events: PropEvent[] = [];
    this.props.update(dt, car, events);
    if (race) events.forEach(e => this.onProp(e));

    // Efectos: humo, marcas, nitro
    const sliding = car.speed > 6 && (car.drifting || Math.abs(car.slip) > 0.14 || (ctl.handbrake && car.speed > 8));
    const power = Math.min(1, Math.abs(car.slip) * 1.4 + (ctl.throttle ? 0.3 : 0));
    if (sliding) {
      this.emitAcc += dt * (26 + 40 * power);
      [-1, 1].forEach((side, k) => {
        const p = car.rearWheel(side, new THREE.Vector3());
        if (this.skidPrev[k]) this.fx.skid(this.skidPrev[k]!, p, 0.7 + power * 0.3);
        this.skidPrev[k] = p;
      });
      while (this.emitAcc >= 1) { this.emitAcc -= 1; this.fx.puff(car.rearWheel(Math.random() < 0.5 ? -1 : 1, this.v), car.vel, power); }
    } else this.skidPrev = [null, null];
    if (car.boosting) { this.v.copy(car.pos).addScaledVector(car.fwd, -2.4).setY(0.5); this.fx.sparkle(this.v, 2); }
    this.fx.update(dt); this.scenery.update(dt);
    if (race) sound.engine(Math.min(1, car.speed / 45), ctl.throttle, sliding ? power : 0);

    this.updateCamera(dt);

    if ((this.hudT -= dt) <= 0) { this.hudT = 0.1; if (race) this.emitHud(); this.drawMap(); }
  }

  private onProp(e: PropEvent) {
    const boost = this.mult * (this.x2 > 0 ? 2 : 1);
    if (e.type === 'cone') { sound.cone(); this.score = Math.max(0, this.score - 200); this.breakCombo('¡CONO! −200'); this.fx.burst(e.pos, 8, 6); }
    else if (e.type === 'crash') { sound.crash(); this.shake = 0.8; this.fx.burst(e.pos, 20); this.breakCombo('¡CHOQUE!'); }
    else if (e.type === 'clip') {
      this.clips++; sound.clip(); this.fx.sparkle(e.pos.clone().setY(1.5), 24);
      this.chain += 300 * boost; this.cb.onEvent(`CLIP +${300 * boost}`, this.track.def.neon[1]);
    } else if (e.type === 'near') {
      this.nears++; sound.clip(); this.chain += 250 * boost; this.cb.onEvent(`¡ROZÓN! +${250 * boost}`, '#ffd23f');
    } else if (e.type === 'pickup') {
      sound.pickup(); this.fx.sparkle(e.pos, 20);
      if (e.kind === 'nitro') { this.car.nitro = Math.min(1, this.car.nitro + 0.5); this.cb.onEvent('NITRO +50%', PICK_COLORS.nitro); }
      else if (e.kind === 'x2') { this.x2 = 12; this.cb.onEvent('PUNTOS ×2 (12 s)', PICK_COLORS.x2); }
      else { this.timeLeft += 6; this.cb.onEvent('+6 SEGUNDOS', PICK_COLORS.time); }
    }
  }

  private completeLap() {
    this.bestLap = Math.min(this.bestLap, this.lapTime);
    if (this.lap >= TOTAL_LAPS) { this.finish(true); return; }
    this.lap++; this.nextCp = 1;
    const bonus = Math.round(this.track.def.lapBonus * this.diff.time * (1 - (this.lap - 2) * 0.15));
    this.timeLeft += bonus; this.lapTime = 0;
    this.props.reset(this.lap, this.hint * 2);
    sound.lap(); this.cb.onEvent(`VUELTA ${this.lap}/${TOTAL_LAPS} · +${bonus} s`, '#5cff7a', true);
  }

  private finish(finished: boolean) {
    this.bank();
    const timeBonus = finished ? Math.round(Math.max(0, this.timeLeft) * 100) : 0;
    this.score += timeBonus; this.mode = 'over'; sound.silence();
    if (finished) sound.lap(); else sound.over();
    this.emitHud();
    this.cb.onOver({ score: Math.round(this.score), finished, laps: finished ? TOTAL_LAPS : this.lap - 1, bestLap: this.bestLap, maxChain: this.maxChain, clips: this.clips, nears: this.nears, timeBonus });
  }

  private updateCamera(dt: number) {
    const car = this.car, cam = this.camera;
    if (this.mode === 'attract') {
      const a = this.t * 0.22;
      this.v.set(Math.cos(a) * 11, 4.2 + Math.sin(this.t * 0.4), Math.sin(a) * 11).add(car.pos);
      cam.position.lerp(this.v, 1 - Math.exp(-dt * 3));
      cam.lookAt(this.w.copy(car.pos).setY(1));
    } else {
      const vd = car.speed > 3 ? this.v.copy(car.vel).normalize() : this.v.copy(car.fwd);
      this.look.copy(car.fwd).multiplyScalar(0.5).addScaledVector(vd, 0.5).normalize();
      const side = Math.max(-3.5, Math.min(3.5, -car.slip * 4)) + 1.4;
      const dist = 7.2 + car.speed * 0.045;
      this.w.set(-this.look.z, 0, this.look.x); // derecha de la dirección de mirada
      this.v.copy(car.pos).addScaledVector(this.look, -dist).addScaledVector(this.w, -side).setY(3.7);
      cam.position.lerp(this.v, 1 - Math.exp(-dt * 6));
      this.w.copy(car.pos).addScaledVector(this.look, 3.5).setY(1);
      cam.lookAt(this.w);
    }
    this.shake = Math.max(0, this.shake - dt * 2.2);
    if (this.shake > 0) cam.position.add(this.v.set((Math.random() - 0.5) * this.shake, (Math.random() - 0.5) * this.shake, 0));
    const fov = 60 + Math.min(1, car.speed / 45) * 12 + (car.boosting ? 6 : 0);
    if (Math.abs(cam.fov - fov) > 0.05) { cam.fov += (fov - cam.fov) * Math.min(1, dt * 4); cam.updateProjectionMatrix(); }
    const h = this.renderer.domElement.height;
    this.fx.setScale(h / (2 * Math.tan((cam.fov * Math.PI) / 360)));
  }

  private emitHud() {
    const car = this.car;
    this.cb.onHud({
      score: this.score, chain: this.chain, mult: this.mult, x2: this.x2, angle: Math.min(1, Math.abs(car.slip) / 1.2), drifting: car.drifting && this.chain > 0,
      comboT: (this.chainT % 2.2) / 2.2, kmh: Math.round(car.speed * 3.6), speedN: Math.min(1, car.speed / 50),
      lap: this.lap, laps: TOTAL_LAPS, timeLeft: Math.max(0, this.timeLeft), lapTime: this.lapTime, bestLap: this.bestLap,
      nitro: car.nitro, boosting: car.boosting, wrong: this.wrong,
    });
  }

  private drawMap() {
    const c = this.minimap; if (!c || !this.mapPts.length) return;
    const g = c.getContext('2d'); if (!g) return;
    const xs = this.mapPts.map(p => p[0]), zs = this.mapPts.map(p => p[1]);
    const x0 = Math.min(...xs), x1 = Math.max(...xs), z0 = Math.min(...zs), z1 = Math.max(...zs);
    const s = Math.min((c.width - 16) / (x1 - x0), (c.height - 16) / (z1 - z0));
    const X = (x: number) => (c.width - (x1 - x0) * s) / 2 + (x - x0) * s, Z = (z: number) => (c.height - (z1 - z0) * s) / 2 + (z - z0) * s;
    g.clearRect(0, 0, c.width, c.height);
    g.lineWidth = 5; g.strokeStyle = 'rgba(255,255,255,0.18)'; g.lineJoin = 'round'; g.beginPath();
    this.mapPts.forEach(([x, z], i) => (i ? g.lineTo(X(x), Z(z)) : g.moveTo(X(x), Z(z)))); g.closePath(); g.stroke();
    g.lineWidth = 1.5; g.strokeStyle = this.track.def.neon[0]; g.stroke();
    g.fillStyle = '#ffffff'; this.props.trafficPositions().forEach(p => { g.beginPath(); g.arc(X(p.x), Z(p.z), 2.5, 0, 7); g.fill(); });
    g.fillStyle = PLAYER_ACCENT; g.shadowColor = PLAYER_ACCENT; g.shadowBlur = 8;
    g.beginPath(); g.arc(X(this.car.pos.x), Z(this.car.pos.z), 4.5, 0, 7); g.fill(); g.shadowBlur = 0;
  }

  dispose() {
    cancelAnimationFrame(this.raf); this.ro.disconnect(); this.input.dispose(); sound.silence();
    if (this.world) disposeTree(this.world);
    disposeTree(this.fx.group);
    this.renderer.dispose(); this.renderer.domElement.remove();
  }
}

import * as THREE from 'three';
import { rawColor } from './three-compat';

const VERT = `
attribute float aSize; attribute float aAlpha; varying float vA; uniform float uScale;
void main() {
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_PointSize = min(aSize * uScale / max(-mv.z, 0.5), 600.0);
  gl_Position = projectionMatrix * mv; vA = aAlpha;
}`;
const FRAG = `
uniform vec3 uColor; varying float vA;
void main() {
  float d = length(gl_PointCoord - 0.5) * 2.0;
  float a = smoothstep(1.0, 0.15, d);
  gl_FragColor = vec4(uColor * (0.75 + 0.35 * (1.0 - d)), a * a * vA);
}`;

/** Sistema de partículas en un único Points con tamaño y opacidad por partícula. */
class Particles {
  readonly points: THREE.Points;
  private pos: Float32Array; private size: Float32Array; private alpha: Float32Array;
  private vel: Float32Array; private age: Float32Array; private life: Float32Array; private s0: Float32Array; private s1: Float32Array;
  private next = 0;
  readonly mat: THREE.ShaderMaterial;

  constructor(readonly n: number, color: string, additive: boolean, private gravity: number, private drag: number, private a0: number) {
    this.pos = new Float32Array(n * 3); this.size = new Float32Array(n); this.alpha = new Float32Array(n);
    this.vel = new Float32Array(n * 3); this.age = new Float32Array(n).fill(9); this.life = new Float32Array(n).fill(1);
    this.s0 = new Float32Array(n); this.s1 = new Float32Array(n);
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    g.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    g.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1));
    this.mat = new THREE.ShaderMaterial({
      vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
      uniforms: { uScale: { value: 400 }, uColor: { value: rawColor(color) } },
    });
    this.points = new THREE.Points(g, this.mat);
    this.points.frustumCulled = false;
  }

  emit(p: THREE.Vector3, v: THREE.Vector3, life: number, s0: number, s1: number) {
    const i = this.next; this.next = (this.next + 1) % this.n;
    this.pos.set([p.x, p.y, p.z], i * 3); this.vel.set([v.x, v.y, v.z], i * 3);
    this.age[i] = 0; this.life[i] = life; this.s0[i] = s0; this.s1[i] = s1;
  }

  update(dt: number) {
    const k = Math.pow(this.drag, dt * 60);
    for (let i = 0; i < this.n; i++) {
      const t = (this.age[i] += dt) / this.life[i];
      if (t >= 1) { this.alpha[i] = 0; this.size[i] = 0; continue; }
      const j = i * 3;
      this.vel[j] *= k; this.vel[j + 2] *= k; this.vel[j + 1] = this.vel[j + 1] * k + this.gravity * dt;
      this.pos[j] += this.vel[j] * dt; this.pos[j + 1] += this.vel[j + 1] * dt; this.pos[j + 2] += this.vel[j + 2] * dt;
      if (this.pos[j + 1] < 0.05) { this.pos[j + 1] = 0.05; this.vel[j + 1] *= -0.4; }
      this.size[i] = this.s0[i] + (this.s1[i] - this.s0[i]) * Math.sqrt(t);
      this.alpha[i] = this.a0 * Math.min(1, t * 8) * (1 - t);
    }
    const g = this.points.geometry;
    (g.getAttribute('position') as THREE.BufferAttribute).needsUpdate = true;
    (g.getAttribute('aSize') as THREE.BufferAttribute).needsUpdate = true;
    (g.getAttribute('aAlpha') as THREE.BufferAttribute).needsUpdate = true;
  }

  clear() { this.age.fill(9); this.alpha.fill(0); }
}

/** Humo de neumáticos, chispas y marcas de derrape en el asfalto. */
export class Fx {
  readonly group = new THREE.Group();
  readonly smoke = new Particles(420, '#cfc8e6', false, 0.9, 0.955, 0.36);
  readonly sparks = new Particles(160, '#ffb347', true, -14, 0.985, 1);
  readonly glow = new Particles(90, '#ff2a6d', true, 1.5, 0.95, 0.8);
  private skids: THREE.InstancedMesh;
  private skidI = 0;
  private m = new THREE.Matrix4(); private q = new THREE.Quaternion(); private sc = new THREE.Vector3(); private mid = new THREE.Vector3();
  private up = new THREE.Vector3(0, 1, 0); private v = new THREE.Vector3();

  constructor() {
    const geo = new THREE.PlaneGeometry(1, 1); geo.rotateX(-Math.PI / 2);
    this.skids = new THREE.InstancedMesh(geo, new THREE.MeshBasicMaterial({
      color: 0x000000, transparent: true, opacity: 0.6, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2,
    }), 1800);
    this.skids.frustumCulled = false;
    this.clearSkids();
    this.group.add(this.skids, this.smoke.points, this.sparks.points, this.glow.points);
  }

  setTint(smoke: string, glow: string) {
    (this.smoke.mat.uniforms.uColor.value as THREE.Vector3).copy(rawColor(smoke));
    (this.glow.mat.uniforms.uColor.value as THREE.Vector3).copy(rawColor(glow));
  }

  setScale(px: number) { [this.smoke, this.sparks, this.glow].forEach(p => { p.mat.uniforms.uScale.value = px; }); }

  puff(p: THREE.Vector3, carVel: THREE.Vector3, power: number) {
    this.v.set(carVel.x * 0.25 + (Math.random() - 0.5) * 2.5, 0.6 + Math.random() * 1.2, carVel.z * 0.25 + (Math.random() - 0.5) * 2.5);
    this.mid.copy(p).setY(0.35);
    this.smoke.emit(this.mid, this.v, 1.6 + Math.random() * 1.2 * power, 1.4, 4 + power * 3.5);
  }

  burst(p: THREE.Vector3, n: number, speed = 9) {
    for (let i = 0; i < n; i++) {
      this.v.set((Math.random() - 0.5) * speed, Math.random() * speed * 0.8, (Math.random() - 0.5) * speed);
      this.sparks.emit(p, this.v, 0.4 + Math.random() * 0.5, 0.35, 0.1);
    }
  }

  sparkle(p: THREE.Vector3, n: number) {
    for (let i = 0; i < n; i++) {
      this.v.set((Math.random() - 0.5) * 6, 1 + Math.random() * 4, (Math.random() - 0.5) * 6);
      this.glow.emit(p, this.v, 0.7 + Math.random() * 0.4, 1.4, 0.2);
    }
  }

  /** Marca de neumático entre a y b. */
  skid(a: THREE.Vector3, b: THREE.Vector3, alpha = 1) {
    const len = a.distanceTo(b); if (len < 0.05 || len > 4) return;
    this.mid.addVectors(a, b).multiplyScalar(0.5).setY(0.025);
    this.q.setFromAxisAngle(this.up, Math.atan2(b.x - a.x, b.z - a.z));
    this.sc.set(0.3 * alpha, 1, len + 0.05);
    this.m.compose(this.mid, this.q, this.sc);
    this.skids.setMatrixAt(this.skidI, this.m);
    this.skidI = (this.skidI + 1) % this.skids.count;
    this.skids.instanceMatrix.needsUpdate = true;
  }

  clearSkids() {
    this.m.makeScale(0, 0, 0);
    for (let i = 0; i < this.skids.count; i++) this.skids.setMatrixAt(i, this.m);
    this.skids.instanceMatrix.needsUpdate = true;
  }

  update(dt: number) { this.smoke.update(dt); this.sparks.update(dt); this.glow.update(dt); }

  reset() { this.smoke.clear(); this.sparks.clear(); this.glow.clear(); this.clearSkids(); }
}

// Entrada: teclado (flechas / WASD) escuchado en window + botones táctiles virtuales.
export interface VirtualPad { up: boolean; down: boolean; left: boolean; right: boolean; brake: boolean; nitro: boolean }

const BLOCK = ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'];

export class Input {
  private keys = new Set<string>();
  readonly virtual: VirtualPad = { up: false, down: false, left: false, right: false, brake: false, nitro: false };

  private onDown = (e: KeyboardEvent) => { if (BLOCK.includes(e.code)) e.preventDefault(); this.keys.add(e.code); };
  private onUp = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private onBlur = () => { this.keys.clear(); };

  constructor() {
    window.addEventListener('keydown', this.onDown);
    window.addEventListener('keyup', this.onUp);
    window.addEventListener('blur', this.onBlur);
  }

  private any(...codes: string[]) { return codes.some(c => this.keys.has(c)); }
  get throttle() { return this.virtual.up || this.any('ArrowUp', 'KeyW') ? 1 : 0; }
  get brake() { return this.virtual.down || this.any('ArrowDown', 'KeyS') ? 1 : 0; }
  get steer() {
    return (this.virtual.right || this.any('ArrowRight', 'KeyD') ? 1 : 0) - (this.virtual.left || this.any('ArrowLeft', 'KeyA') ? 1 : 0);
  }
  /** Freno de mano: inicia el derrape. */
  get handbrake() { return this.virtual.brake || this.any('Space'); }
  get nitro() { return this.virtual.nitro || this.any('ShiftLeft', 'ShiftRight', 'KeyN', 'KeyX'); }

  reset() { this.keys.clear(); Object.assign(this.virtual, { up: false, down: false, left: false, right: false, brake: false, nitro: false }); }

  dispose() {
    window.removeEventListener('keydown', this.onDown);
    window.removeEventListener('keyup', this.onUp);
    window.removeEventListener('blur', this.onBlur);
  }
}

import * as THREE from 'three';
import { buildCarMesh, Car, CarMesh } from './car';
import { DiffDef } from './config';
import { canvasTexture, disposeTree, lin, radialTexture } from './three-compat';
import type { Track } from './track';

export type PickKind = 'nitro' | 'x2' | 'time';
export interface PropEvent { type: 'cone' | 'pickup' | 'clip' | 'crash' | 'near'; kind?: PickKind; pos: THREE.Vector3 }

interface Cone { pos: THREE.Vector3; vel: THREE.Vector3; rot: number; knocked: boolean }
interface Pick { kind: PickKind; mesh: THREE.Group; taken: boolean }
interface Clip { pos: THREE.Vector3; mesh: THREE.Group; done: boolean }
interface Traffic { car: CarMesh; d: number; lat: number; speed: number; near: number; pos: THREE.Vector3; tan: THREE.Vector3 }

export const PICK_COLORS: Record<PickKind, string> = { nitro: '#38e8ff', x2: '#ff3df0', time: '#5cff7a' };
const TRAFFIC_PAINT = ['#2b3a67', '#e8e2d0', '#1a1a1a', '#8c1c2a', '#cfd6dd', '#3e6b48'];

export class Props {
  readonly group = new THREE.Group();
  private cones: Cone[] = [];
  private coneMesh: THREE.InstancedMesh;
  private picks: Pick[] = [];
  private clips: Clip[] = [];
  private traffic: Traffic[] = [];
  private t = 0;
  private m = new THREE.Matrix4(); private q = new THREE.Quaternion(); private e = new THREE.Euler(); private one = new THREE.Vector3(1, 1, 1);
  private tmp = new THREE.Vector3();

  constructor(private track: Track, public diff: DiffDef) {
    const cg = new THREE.ConeGeometry(0.34, 0.85, 10); cg.translate(0, 0.42, 0);
    const tex = canvasTexture(32, 64, g => { g.fillStyle = '#ff6a12'; g.fillRect(0, 0, 32, 64); g.fillStyle = '#f4f4f4'; g.fillRect(0, 22, 32, 12); });
    this.coneMesh = new THREE.InstancedMesh(cg, new THREE.MeshLambertMaterial({ map: tex, emissive: lin('#3a1200') }), 24);
    this.group.add(this.coneMesh);
    // Puntos de clip en el exterior de las curvas más cerradas
    const clipTex = radialTexture([[0, '#ffffff'], [0.2, track.def.neon[1]], [0.55, track.def.neon[1] + '44'], [1, track.def.neon[1] + '00']]);
    const ringTex = canvasTexture(128, 128, g => {
      g.strokeStyle = track.def.neon[1]; g.lineWidth = 8; g.shadowColor = track.def.neon[1]; g.shadowBlur = 14;
      g.beginPath(); g.arc(64, 64, 50, 0, Math.PI * 2); g.stroke();
    });
    track.corners(28).slice(0, 7).forEach(i => {
      const side = Math.sign(track.curv[i]) || 1, pos = track.pts[i].clone().addScaledVector(track.right[i], side * (track.half + 0.6));
      const mesh = new THREE.Group();
      const post = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 2.6, 6), new THREE.MeshBasicMaterial({ color: lin(track.def.neon[1]) }));
      post.position.y = 1.3;
      const halo = new THREE.Sprite(new THREE.SpriteMaterial({ map: clipTex, blending: THREE.AdditiveBlending, depthWrite: false })); halo.position.y = 2.8; halo.scale.set(4, 4, 1);
      const ring = new THREE.Mesh(new THREE.PlaneGeometry(9, 9), new THREE.MeshBasicMaterial({ map: ringTex, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false }));
      ring.rotation.x = -Math.PI / 2; ring.position.y = 0.04;
      mesh.add(post, halo, ring); mesh.position.copy(pos);
      this.group.add(mesh); this.clips.push({ pos, mesh, done: false });
    });
  }

  /** Recoloca conos, power-ups y tráfico al empezar cada vuelta (progresión: más tráfico y conos). */
  reset(lap: number, playerD: number) {
    const t = this.track, L = t.length, rnd = Math.random;
    this.cones = [];
    const groups = Math.min(7, Math.ceil((this.diff.cones + lap * 2) / 3));
    for (let k = 0; k < groups; k++) {
      const d = playerD + 70 + (k + rnd() * 0.6) * ((L - 110) / groups), lat = (rnd() - 0.5) * (t.half * 2 - 4);
      for (let c = 0; c < 3; c++) {
        const p = t.at(d + c * 3.2, lat + (c - 1) * 1.2);
        this.cones.push({ pos: p.setY(0), vel: new THREE.Vector3(), rot: 0, knocked: false });
      }
    }
    this.picks.forEach(p => { this.group.remove(p.mesh); disposeTree(p.mesh); });
    this.picks = [];
    const kinds: PickKind[] = ['nitro', 'x2', 'time', 'nitro', 'time'];
    kinds.forEach((kind, k) => {
      const mesh = new THREE.Group();
      const gem = new THREE.Mesh(new THREE.OctahedronGeometry(0.75), new THREE.MeshBasicMaterial({ color: lin(PICK_COLORS[kind]) }));
      const halo = new THREE.Sprite(new THREE.SpriteMaterial({ map: radialTexture([[0, PICK_COLORS[kind]], [0.4, PICK_COLORS[kind] + '55'], [1, PICK_COLORS[kind] + '00']]), blending: THREE.AdditiveBlending, depthWrite: false }));
      halo.scale.set(4.5, 4.5, 1); mesh.add(gem, halo);
      mesh.position.copy(t.at(playerD + 110 + (k + 0.3 + rnd() * 0.4) * ((L - 150) / kinds.length), (rnd() - 0.5) * (t.half * 2 - 5))).setY(1.3);
      this.group.add(mesh); this.picks.push({ kind, mesh, taken: false });
    });
    this.clips.forEach(c => { c.done = false; c.mesh.visible = true; });
    this.traffic.forEach(tr => { this.group.remove(tr.car.root); disposeTree(tr.car.root); });
    this.traffic = [];
    const n = this.diff.traffic + lap - 1;
    for (let k = 0; k < n; k++) {
      const car = buildCarMesh(TRAFFIC_PAINT[(k + lap) % TRAFFIC_PAINT.length], '#ffffff', false);
      car.root.scale.setScalar(0.98); this.group.add(car.root);
      this.traffic.push({ car, d: playerD + 90 + k * (L / (n + 0.5)), lat: (k % 2 ? 1 : -1) * t.half * 0.45, speed: 10 + rnd() * 6, near: 0, pos: new THREE.Vector3(), tan: new THREE.Vector3() });
    }
    this.syncCones();
  }

  private syncCones() {
    this.coneMesh.count = this.cones.length;
    this.cones.forEach((c, i) => {
      this.e.set(c.knocked ? c.rot : 0, c.rot * 0.7, c.knocked ? c.rot * 0.5 : 0);
      this.coneMesh.setMatrixAt(i, this.m.compose(c.pos, this.q.setFromEuler(this.e), this.one));
    });
    this.coneMesh.instanceMatrix.needsUpdate = true;
  }

  update(dt: number, car: Car, events: PropEvent[]) {
    this.t += dt;
    const p = car.pos;
    for (const c of this.cones) {
      if (c.knocked) {
        c.vel.y -= 22 * dt; c.pos.addScaledVector(c.vel, dt); c.rot += dt * 9;
        if (c.pos.y < 0) { c.pos.y = 0; c.vel.multiplyScalar(0.5); c.vel.y = Math.abs(c.vel.y) * 0.3; }
      } else if ((c.pos.x - p.x) ** 2 + (c.pos.z - p.z) ** 2 < 2.4 ** 2) {
        c.knocked = true; c.vel.copy(car.vel).multiplyScalar(0.7).add(this.tmp.set((Math.random() - 0.5) * 6, 7 + Math.random() * 4, (Math.random() - 0.5) * 6));
        events.push({ type: 'cone', pos: c.pos.clone() });
      }
    }
    this.syncCones();
    for (const k of this.picks) {
      if (k.taken) continue;
      k.mesh.rotation.y += dt * 2.4; k.mesh.position.y = 1.3 + Math.sin(this.t * 3 + k.mesh.position.x) * 0.25;
      if (k.mesh.position.distanceToSquared(this.tmp.copy(p).setY(1.3)) < 3.2 ** 2) { k.taken = true; k.mesh.visible = false; events.push({ type: 'pickup', kind: k.kind, pos: k.mesh.position.clone() }); }
    }
    const rear = this.tmp.copy(p).addScaledVector(car.fwd, -1.8);
    for (const c of this.clips) {
      if (c.done) continue;
      if (car.drifting && (c.pos.x - rear.x) ** 2 + (c.pos.z - rear.z) ** 2 < 5.2 ** 2) {
        c.done = true; c.mesh.visible = false; events.push({ type: 'clip', pos: c.pos.clone() });
      }
    }
    for (const tr of this.traffic) {
      tr.d += tr.speed * dt; tr.near = Math.max(0, tr.near - dt);
      this.track.at(tr.d, tr.lat, tr.pos, tr.tan);
      tr.car.root.position.copy(tr.pos); tr.car.root.rotation.y = Math.atan2(tr.tan.x, tr.tan.z);
      tr.car.wheels.forEach(w => { w.rotation.x += tr.speed * dt / 0.37; });
      const dx = p.x - tr.pos.x, dz = p.z - tr.pos.z, dist = Math.hypot(dx, dz);
      if (dist < 2.7) {
        const nx = dx / (dist || 1), nz = dz / (dist || 1), vn = car.vel.x * nx + car.vel.z * nz;
        if (vn < 0) { car.vel.x -= 1.6 * vn * nx; car.vel.z -= 1.6 * vn * nz; }
        car.pos.x = tr.pos.x + nx * 2.7; car.pos.z = tr.pos.z + nz * 2.7; car.vel.multiplyScalar(0.7);
        if (tr.near < 1.5) events.push({ type: 'crash', pos: tr.pos.clone().setY(0.8) });
        tr.near = 2; tr.speed = Math.max(tr.speed, 14);
      } else if (dist < 6 && car.drifting && tr.near <= 0) {
        tr.near = 2.5; events.push({ type: 'near', pos: tr.pos.clone() });
      }
    }
  }

  /** Posiciones de los coches de tráfico (para el minimapa). */
  trafficPositions() { return this.traffic.map(t => t.pos); }
}

import * as THREE from 'three';
import { canvasTexture, LIGHT_K, lin, radialTexture, rawColor } from './three-compat';
import type { Track } from './track';

const SIGNS: Record<string, string[]> = {
  touge: ['TOUGE', 'NIGHT RUN', '24H', 'TOFU', 'RAMEN'],
  port: ['DOCK 7', 'TURBO', 'NEO PORT', 'DRIFT', 'CARGO'],
  city: ['KINGS', 'SHUTO', 'ZERO', 'NEON', 'HYPER', 'RAMEN'],
};

function neonSign(text: string, color: string) {
  const w = 64 + text.length * 46;
  const tex = canvasTexture(w, 96, g => {
    g.fillStyle = 'rgba(8,4,16,0.92)'; g.fillRect(0, 0, w, 96);
    g.strokeStyle = color; g.lineWidth = 5; g.shadowColor = color; g.shadowBlur = 18; g.strokeRect(8, 8, w - 16, 80);
    g.font = 'italic 900 58px Arial, sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillStyle = color; g.fillText(text, w / 2, 50); g.shadowBlur = 0; g.fillStyle = '#ffffff'; g.globalAlpha = 0.7; g.fillText(text, w / 2, 50);
  });
  return new THREE.Mesh(new THREE.PlaneGeometry(w / 24, 4), new THREE.MeshBasicMaterial({ map: tex, side: THREE.DoubleSide }));
}

export class Scenery {
  readonly group = new THREE.Group();
  private flicker: THREE.MeshBasicMaterial[] = [];
  private blink: THREE.Sprite[] = [];
  private t = 0;
  private rand: () => number;

  constructor(private track: Track, scene: THREE.Scene) {
    const d = track.def;
    let seed = d.id.length * 9301 + 49297;
    this.rand = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
    scene.background = lin(d.fog);
    scene.fog = new THREE.FogExp2(lin(d.fog).getHex(), d.fogDensity);

    // Cielo con degradado + estrellas + luna
    const sky = new THREE.Mesh(new THREE.SphereGeometry(700, 24, 12), new THREE.ShaderMaterial({
      side: THREE.BackSide, depthWrite: false,
      uniforms: { top: { value: rawColor(d.skyTop) }, bot: { value: rawColor(d.skyBottom) } },
      vertexShader: 'varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
      fragmentShader: 'uniform vec3 top; uniform vec3 bot; varying vec3 vP; void main(){ float h = clamp(normalize(vP).y * 2.2, 0.0, 1.0); gl_FragColor = vec4(mix(bot, top, pow(h, 0.6)), 1.0); }',
    }));
    this.group.add(sky);
    const sp: number[] = [];
    for (let i = 0; i < 700; i++) {
      const a = this.rand() * Math.PI * 2, e = 0.12 + this.rand() * 1.3;
      sp.push(Math.cos(a) * Math.cos(e) * 650, Math.sin(e) * 650, Math.sin(a) * Math.cos(e) * 650);
    }
    const sg = new THREE.BufferGeometry(); sg.setAttribute('position', new THREE.Float32BufferAttribute(sp, 3));
    this.group.add(new THREE.Points(sg, new THREE.PointsMaterial({ color: 0xffffff, size: 1.6, sizeAttenuation: false, fog: false, transparent: true, opacity: 0.8 })));
    const moon = new THREE.Sprite(new THREE.SpriteMaterial({ map: radialTexture([[0, '#fffbe8'], [0.22, '#fff3d0'], [0.27, 'rgba(255,220,255,0.35)'], [1, 'rgba(255,200,255,0)']], 128), fog: false, depthWrite: false }));
    moon.position.set(-260, 230, -420); moon.scale.set(150, 150, 1); this.group.add(moon);

    // Suelo
    const groundTex = canvasTexture(256, 256, g => {
      g.fillStyle = '#808080'; g.fillRect(0, 0, 256, 256);
      for (let i = 0; i < 3000; i++) { const v = 90 + this.rand() * 90; g.fillStyle = `rgb(${v},${v},${v})`; g.fillRect(this.rand() * 256, this.rand() * 256, 3, 3); }
    }, true);
    groundTex.repeat.set(90, 90);
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(1600, 1600), new THREE.MeshBasicMaterial({ map: groundTex, color: lin(d.ground) }));
    ground.rotation.x = -Math.PI / 2; ground.position.y = -0.06; this.group.add(ground);

    // Luces
    this.group.add(new THREE.HemisphereLight(lin('#8a84c8').getHex(), lin('#1b1420').getHex(), 0.95 * LIGHT_K));

    this.lamps();
    if (d.kind === 'touge') this.touge(); else if (d.kind === 'port') this.port(); else this.city();
    this.signs();
  }

  private free(x: number, z: number, clear: number) { return Math.abs(this.track.query(new THREE.Vector3(x, 0, z)).lateral) > this.track.wallOff + clear; }

  /** Busca un punto libre cerca de la pista (entre min y max metros del muro). */
  private spot(min: number, max: number) {
    const t = this.track, N = t.pts.length;
    for (let k = 0; k < 20; k++) {
      const i = Math.floor(this.rand() * N), s = this.rand() < 0.5 ? -1 : 1, off = t.wallOff + min + this.rand() * (max - min);
      const p = t.pts[i].clone().addScaledVector(t.right[i], s * off);
      if (this.free(p.x, p.z, min * 0.8)) return { p, i, s };
    }
    return null;
  }

  private lamps() {
    const t = this.track, d = t.def, N = t.pts.length, step = 14, count = Math.floor(N / step);
    const poleGeo = new THREE.CylinderGeometry(0.12, 0.16, 8, 6); poleGeo.translate(0, 4, 0);
    const poles = new THREE.InstancedMesh(poleGeo, new THREE.MeshLambertMaterial({ color: lin('#2a2833') }), count);
    const headGeo = new THREE.BoxGeometry(0.5, 0.25, 1.6);
    const heads = new THREE.InstancedMesh(headGeo, new THREE.MeshBasicMaterial({ color: lin('#fff1d8') }), count);
    const poolGeo = new THREE.PlaneGeometry(16, 16); poolGeo.rotateX(-Math.PI / 2);
    const pools = new THREE.InstancedMesh(poolGeo, new THREE.MeshBasicMaterial({
      map: radialTexture([[0, d.lamp + 'aa'], [0.4, d.lamp + '44'], [1, d.lamp + '00']], 128), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false,
    }), count);
    const haloMat = new THREE.SpriteMaterial({ map: radialTexture([[0, '#ffffff'], [0.15, d.lamp], [0.5, d.lamp + '33'], [1, d.lamp + '00']]), blending: THREE.AdditiveBlending, depthWrite: false, transparent: true });
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), up = new THREE.Vector3(0, 1, 0), one = new THREE.Vector3(1, 1, 1);
    for (let k = 0; k < count; k++) {
      const i = k * step, s = k % 2 ? 1 : -1, base = t.pts[i].clone().addScaledVector(t.right[i], s * (t.wallOff + 0.8));
      const ang = Math.atan2(t.right[i].x, t.right[i].z);
      q.setFromAxisAngle(up, ang);
      poles.setMatrixAt(k, m.compose(base, q, one));
      const head = base.clone().addScaledVector(t.right[i], -s * 0.7).setY(8);
      heads.setMatrixAt(k, m.compose(head, q, one));
      pools.setMatrixAt(k, m.compose(t.pts[i].clone().addScaledVector(t.right[i], s * (t.half * 0.45)).setY(0.03), q, one));
      const halo = new THREE.Sprite(haloMat); halo.position.copy(head).setY(7.8); halo.scale.set(6, 6, 1); this.group.add(halo);
    }
    this.group.add(poles, heads, pools);
  }

  private touge() {
    const mtnMat = new THREE.MeshBasicMaterial({ color: lin('#110c20') });
    for (let i = 0; i < 26; i++) {
      const a = (i / 26) * Math.PI * 2, r = 380 + this.rand() * 160, h = 90 + this.rand() * 150;
      const c = new THREE.Mesh(new THREE.ConeGeometry(70 + this.rand() * 60, h, 7), mtnMat);
      c.position.set(Math.cos(a) * r, h / 2 - 8, Math.sin(a) * r); this.group.add(c);
    }
    const n = 340, trunk = new THREE.CylinderGeometry(0.25, 0.35, 2, 5); trunk.translate(0, 1, 0);
    const crown = new THREE.ConeGeometry(2.2, 7, 7); crown.translate(0, 5.2, 0);
    const trunks = new THREE.InstancedMesh(trunk, new THREE.MeshLambertMaterial({ color: lin('#2a1c14') }), n);
    const crowns = new THREE.InstancedMesh(crown, new THREE.MeshLambertMaterial({ color: 0xffffff }), n);
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), sc = new THREE.Vector3();
    let k = 0;
    for (let tries = 0; tries < 900 && k < n; tries++) {
      const s = this.spot(3, 40); if (!s) continue;
      sc.setScalar(0.7 + this.rand() * 0.9); m.compose(s.p, q, sc);
      trunks.setMatrixAt(k, m); crowns.setMatrixAt(k, m); crowns.setColorAt(k, lin(this.rand() < 0.5 ? '#1c3a2a' : '#24472f')); k++;
    }
    trunks.count = crowns.count = k; this.group.add(trunks, crowns);
    // Ciudad lejana en el valle
    const cp: number[] = [], cc: number[] = [];
    for (let i = 0; i < 900; i++) {
      const a = this.rand() * Math.PI * 2, r = 250 + this.rand() * 200;
      cp.push(Math.cos(a) * r, 0.5 + this.rand() * 3, Math.sin(a) * r);
      const c = lin(['#ffb25e', '#ff6ea8', '#7fe9ff', '#fff2c4'][Math.floor(this.rand() * 4)]); cc.push(c.r, c.g, c.b);
    }
    const cg = new THREE.BufferGeometry(); cg.setAttribute('position', new THREE.Float32BufferAttribute(cp, 3)); cg.setAttribute('color', new THREE.Float32BufferAttribute(cc, 3));
    this.group.add(new THREE.Points(cg, new THREE.PointsMaterial({ size: 2.2, sizeAttenuation: false, vertexColors: true, fog: false })));
    // Torii sobre la carretera y máquinas expendedoras
    const t = this.track, i0 = Math.floor(t.pts.length * 0.52), red = new THREE.MeshLambertMaterial({ color: lin('#d4202c'), emissive: lin('#3a0508') });
    const torii = new THREE.Group(), w = t.wallOff + 1;
    [-1, 1].forEach(s => { const p = new THREE.Mesh(new THREE.CylinderGeometry(0.45, 0.5, 9, 10), red); p.position.set(s * w, 4.5, 0); torii.add(p); });
    const top = new THREE.Mesh(new THREE.BoxGeometry(w * 2 + 5, 0.7, 1.1), new THREE.MeshLambertMaterial({ color: lin('#1a1014') })); top.position.y = 9.3; torii.add(top);
    const bar = new THREE.Mesh(new THREE.BoxGeometry(w * 2 + 2, 0.5, 0.6), red); bar.position.y = 7.6; torii.add(bar);
    torii.position.copy(t.pts[i0]); torii.rotation.y = Math.atan2(t.tan[i0].x, t.tan[i0].z); this.group.add(torii);
    const vend = new THREE.MeshBasicMaterial({ map: canvasTexture(64, 128, g => {
      g.fillStyle = '#e8f4ff'; g.fillRect(0, 0, 64, 128); g.fillStyle = '#1a6dff'; g.fillRect(0, 0, 64, 18);
      for (let y = 0; y < 3; y++) for (let x = 0; x < 4; x++) { g.fillStyle = ['#ff3d5a', '#2ac86e', '#ffb800', '#3d7bff'][(x + y) % 4]; g.fillRect(6 + x * 14, 26 + y * 22, 10, 16); }
      g.fillStyle = '#20232c'; g.fillRect(8, 98, 48, 20);
    }) });
    for (let i = 0; i < 6; i++) {
      const s = this.spot(0.8, 2.5); if (!s) continue;
      const v = new THREE.Mesh(new THREE.BoxGeometry(1.2, 2, 0.9), vend); v.position.copy(s.p).setY(1);
      v.rotation.y = Math.atan2(-s.s * t.right[s.i].x, -s.s * t.right[s.i].z); this.group.add(v);
    }
  }

  private port() {
    const n = 220, geo = new THREE.BoxGeometry(2.5, 2.6, 6.1); geo.translate(0, 1.3, 0);
    const box = new THREE.InstancedMesh(geo, new THREE.MeshLambertMaterial({ map: canvasTexture(64, 64, g => {
      g.fillStyle = '#ffffff'; g.fillRect(0, 0, 64, 64); g.fillStyle = 'rgba(0,0,0,0.28)'; for (let x = 2; x < 64; x += 6) g.fillRect(x, 0, 2, 64);
    }) }), n);
    const pal = ['#c0392b', '#1f6fb2', '#e67e22', '#16a085', '#7d3c98', '#d4ac0d', '#5d6d7e'];
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), one = new THREE.Vector3(1, 1, 1), up = new THREE.Vector3(0, 1, 0);
    let k = 0;
    for (let tries = 0; tries < 400 && k < n - 3; tries++) {
      const s = this.spot(3, 30); if (!s) continue;
      q.setFromAxisAngle(up, Math.atan2(this.track.tan[s.i].x, this.track.tan[s.i].z) + (this.rand() < 0.3 ? Math.PI / 2 : 0));
      const h = 1 + Math.floor(this.rand() * 3);
      for (let y = 0; y < h && k < n; y++) { box.setMatrixAt(k, m.compose(s.p.clone().setY(y * 2.6), q, one)); box.setColorAt(k, lin(pal[Math.floor(this.rand() * pal.length)])); k++; }
    }
    box.count = k; this.group.add(box);
    const steel = new THREE.MeshLambertMaterial({ color: lin('#c8a23a') });
    for (let i = 0; i < 5; i++) {
      const s = this.spot(30, 60); if (!s) continue;
      const crane = new THREE.Group();
      [[-6, -6], [6, -6], [-6, 6], [6, 6]].forEach(([x, z]) => { const l = new THREE.Mesh(new THREE.BoxGeometry(1, 34, 1), steel); l.position.set(x, 17, z); crane.add(l); });
      const boom = new THREE.Mesh(new THREE.BoxGeometry(3, 2.5, 60), steel); boom.position.set(0, 35, 12); crane.add(boom);
      const beacon = new THREE.Sprite(new THREE.SpriteMaterial({ map: radialTexture([[0, '#ffffff'], [0.2, '#ff2030'], [1, 'rgba(255,0,0,0)']]), blending: THREE.AdditiveBlending, depthWrite: false }));
      beacon.position.set(0, 37.5, 40); beacon.scale.set(7, 7, 1); crane.add(beacon); this.blink.push(beacon);
      crane.position.copy(s.p); crane.rotation.y = this.rand() * Math.PI; this.group.add(crane);
    }
  }

  private city() {
    const win = canvasTexture(128, 256, g => {
      g.fillStyle = '#0a0812'; g.fillRect(0, 0, 128, 256);
      for (let y = 4; y < 256; y += 10) for (let x = 4; x < 128; x += 9) {
        if (this.rand() < 0.45) continue;
        const v = this.rand(); g.fillStyle = v < 0.6 ? '#ffd9a0' : v < 0.85 ? '#a8e6ff' : '#ff8fd0'; g.globalAlpha = 0.4 + this.rand() * 0.6; g.fillRect(x, y, 6, 6);
      }
    });
    const geo = new THREE.BoxGeometry(1, 1, 1); geo.translate(0, 0.5, 0);
    const mat = new THREE.MeshLambertMaterial({ map: win, emissive: lin('#ffffff'), emissiveMap: win, color: lin('#3a3550') });
    const n = 150, b = new THREE.InstancedMesh(geo, mat, n);
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), sc = new THREE.Vector3();
    let k = 0;
    for (let tries = 0; tries < 600 && k < n; tries++) {
      const s = this.spot(10, 120); if (!s) continue;
      const w = 12 + this.rand() * 18, h = 25 + this.rand() * 110 * (0.5 + this.rand());
      if (!this.free(s.p.x, s.p.z, w * 0.75 + 4)) continue;
      sc.set(w, h, 12 + this.rand() * 18); b.setMatrixAt(k++, m.compose(s.p, q, sc));
    }
    b.count = k; this.group.add(b);
    const blinkMat = new THREE.SpriteMaterial({ map: radialTexture([[0, '#ffffff'], [0.2, '#ff2030'], [1, 'rgba(255,0,0,0)']]), blending: THREE.AdditiveBlending, depthWrite: false });
    for (let i = 0; i < Math.min(k, 30); i++) {
      b.getMatrixAt(i, m); const p = new THREE.Vector3(), s = new THREE.Vector3(); m.decompose(p, q, s);
      if (s.y < 70) continue;
      const sp = new THREE.Sprite(blinkMat); sp.position.copy(p).setY(s.y + 1.5); sp.scale.set(6, 6, 1); this.group.add(sp); this.blink.push(sp);
    }
  }

  private signs() {
    const d = this.track.def, words = SIGNS[d.kind], t = this.track;
    for (let i = 0; i < 12; i++) {
      const s = this.spot(2, 9); if (!s) continue;
      const color = d.neon[i % 3], sign = neonSign(words[i % words.length], color);
      sign.position.copy(s.p).setY(5 + this.rand() * 4);
      sign.rotation.y = Math.atan2(t.tan[s.i].x, t.tan[s.i].z) + Math.PI / 2 * (s.s > 0 ? -1 : 1) + (this.rand() - 0.5) * 0.6;
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.15, sign.position.y, 5), new THREE.MeshLambertMaterial({ color: lin('#1a1820') }));
      pole.position.copy(s.p).setY(sign.position.y / 2);
      this.group.add(sign, pole);
      if (i % 4 === 1) this.flicker.push(sign.material as THREE.MeshBasicMaterial);
    }
  }

  update(dt: number) {
    this.t += dt;
    this.flicker.forEach((m, i) => { const f = Math.sin(this.t * 23 + i * 7) > 0.92 || Math.sin(this.t * 3.1 + i) > 0.97; m.color.setScalar(f ? 0.35 : 1); });
    const on = Math.sin(this.t * 4) > 0;
    this.blink.forEach(b => { b.visible = on; });
  }
}

import * as THREE from 'three';

// r170 trae gestión de color y r128 no: la desactivamos y linealizamos a mano con lin() → mismo resultado en ambas.
const CM = (THREE as any).ColorManagement;
if (CM && typeof CM.enabled === 'boolean') CM.enabled = false;

/** Color sRGB (#hex) → lineal, para materiales, luces, niebla e instancias. */
export const lin = (c: string | THREE.Color) => new THREE.Color(c).convertSRGBToLinear();

/** Multiplica TODAS las intensidades de luz (r155+ usa unidades físicas). */
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1;

export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any; const T = THREE as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.SRGBColorSpace; else a.outputEncoding = T.sRGBEncoding;
}

export function srgbTexture(t: THREE.Texture) {
  const a = t as any; const T = THREE as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding;
  return t;
}

/** Color hex → vector sRGB "crudo" para shaders propios (sin conversión: igual en r128 y r170). */
export function rawColor(hex: string) {
  const v = parseInt(hex.replace('#', ''), 16);
  return new THREE.Vector3(((v >> 16) & 255) / 255, ((v >> 8) & 255) / 255, (v & 255) / 255);
}

/** Textura desde un canvas 2D dibujado al vuelo. */
export function canvasTexture(w: number, h: number, draw: (g: CanvasRenderingContext2D) => void, repeat = false) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d')!);
  const t = new THREE.CanvasTexture(c);
  if (repeat) { t.wrapS = THREE.RepeatWrapping; t.wrapT = THREE.RepeatWrapping; }
  t.anisotropy = 4;
  return srgbTexture(t);
}

/** Degradado radial (halos, charcos de luz, brillo de neón). */
export function radialTexture(stops: Array<[number, string]>, size = 64) {
  return canvasTexture(size, size, g => {
    const h = size / 2, gr = g.createRadialGradient(h, h, 0, h, h, h);
    stops.forEach(([o, c]) => gr.addColorStop(o, c));
    g.fillStyle = gr; g.fillRect(0, 0, size, size);
  });
}

/** Libera geometrías, materiales y texturas de un subárbol. */
export function disposeTree(o: THREE.Object3D) {
  o.traverse(n => {
    const m = n as THREE.Mesh;
    if (m.geometry) m.geometry.dispose();
    const mats = m.material ? (Array.isArray(m.material) ? m.material : [m.material]) : [];
    mats.forEach(mt => {
      Object.values(mt).forEach(v => { if (v instanceof THREE.Texture) v.dispose(); });
      mt.dispose();
    });
  });
}

import * as THREE from 'three';
import { TrackDef } from './config';
import { canvasTexture, lin } from './three-compat';

export interface TrackHit { idx: number; lateral: number; along: number; tangent: THREE.Vector3; right: THREE.Vector3 }

const SEG = 2; // metros entre muestras

/** Tira de quads entre dos bordes (a, b) a lo largo de la pista; mask decide qué tramos se dibujan. */
function ribbon(n: number, a: (i: number) => THREE.Vector3, b: (i: number) => THREE.Vector3, vLen: number, mask?: (i: number) => boolean) {
  const pos: number[] = [], uv: number[] = [], idx: number[] = [];
  for (let i = 0; i <= n; i++) {
    const k = i % n, A = a(k), B = b(k);
    pos.push(A.x, A.y, A.z, B.x, B.y, B.z);
    uv.push(0, (i * SEG) / vLen, 1, (i * SEG) / vLen);
    if (i < n && (!mask || mask(k))) { const o = i * 2; idx.push(o, o + 1, o + 2, o + 1, o + 3, o + 2); }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

export class Track {
  readonly pts: THREE.Vector3[];
  readonly tan: THREE.Vector3[] = [];
  readonly right: THREE.Vector3[] = [];
  readonly curv: number[] = [];
  readonly half: number;
  readonly wallOff: number;
  readonly length: number;
  readonly group = new THREE.Group();
  private hit: TrackHit = { idx: 0, lateral: 0, along: 0, tangent: new THREE.Vector3(), right: new THREE.Vector3() };

  constructor(readonly def: TrackDef) {
    const curve = new THREE.CatmullRomCurve3(def.pts.map(([x, z]) => new THREE.Vector3(x, 0, z)), true, 'centripetal');
    const n = Math.round(curve.getLength() / SEG);
    this.pts = curve.getSpacedPoints(n); this.pts.pop();
    this.length = this.pts.length * SEG;
    this.half = def.width / 2; this.wallOff = this.half + 1.7;
    const N = this.pts.length;
    for (let i = 0; i < N; i++) {
      const t = this.pts[(i + 1) % N].clone().sub(this.pts[(i - 1 + N) % N]).normalize();
      this.tan.push(t); this.right.push(new THREE.Vector3(-t.z, 0, t.x));
    }
    for (let i = 0; i < N; i++) {
      const a = this.tan[(i - 3 + N) % N], b = this.tan[(i + 3) % N];
      this.curv.push((a.x * b.z - a.z * b.x) / (6 * SEG)); // + = gira a la izquierda
    }
    this.build();
  }

  private edge(i: number, off: number, y = 0) { return this.pts[i].clone().addScaledVector(this.right[i], off).setY(y); }

  private build() {
    const N = this.pts.length, d = this.def, h = this.half, w = this.wallOff;
    // Asfalto
    const asphalt = canvasTexture(256, 512, g => {
      g.fillStyle = '#26262c'; g.fillRect(0, 0, 256, 512);
      for (let k = 0; k < 5000; k++) { const v = 25 + Math.random() * 40; g.fillStyle = `rgba(${v},${v},${v + 6},0.55)`; g.fillRect(Math.random() * 256, Math.random() * 512, 2, 2); }
      g.fillStyle = 'rgba(0,0,0,0.22)'; for (let k = 0; k < 14; k++) g.fillRect(Math.random() * 256, Math.random() * 512, 30 + Math.random() * 60, 4 + Math.random() * 10);
      g.fillStyle = '#e9e9f0'; g.fillRect(8, 0, 7, 512); g.fillRect(241, 0, 7, 512);
      g.fillStyle = '#f2c14a'; g.fillRect(124, 0, 8, 220);
    }, true);
    const road = new THREE.Mesh(ribbon(N, i => this.edge(i, -h), i => this.edge(i, h), 18),
      new THREE.MeshPhongMaterial({ map: asphalt, color: lin('#d8d6e6'), specular: lin('#3a3550'), shininess: 40 }));
    this.group.add(road);

    // Pianos en las curvas
    const kerbTex = canvasTexture(64, 128, g => { g.fillStyle = '#f4f4f4'; g.fillRect(0, 0, 64, 128); g.fillStyle = '#e8213f'; g.fillRect(0, 0, 64, 64); }, true);
    const kMask = (i: number) => Math.abs(this.curv[i]) > 0.022;
    const kMat = new THREE.MeshLambertMaterial({ map: kerbTex, side: THREE.DoubleSide });
    [-1, 1].forEach(s => this.group.add(new THREE.Mesh(
      ribbon(N, i => this.edge(i, s * h, 0.012), i => this.edge(i, s * (h + 1.3), 0.012), 3, kMask), kMat)));
    // Arcén oscuro hasta el muro
    const shoulder = new THREE.MeshLambertMaterial({ color: lin('#17161d'), side: THREE.DoubleSide });
    [-1, 1].forEach(s => this.group.add(new THREE.Mesh(ribbon(N, i => this.edge(i, s * h, -0.01), i => this.edge(i, s * w, -0.01), 4), shoulder)));

    // Muros / quitamiedos
    const wallTex = canvasTexture(128, 64, g => {
      if (d.kind === 'touge') {
        g.fillStyle = '#0c0d10'; g.fillRect(0, 0, 128, 64);
        g.fillStyle = '#c7ccd4'; g.fillRect(0, 10, 128, 26); g.fillStyle = '#8b929c'; g.fillRect(0, 22, 128, 3);
        g.fillStyle = '#4b5058'; g.fillRect(58, 0, 10, 64);
      } else {
        g.fillStyle = d.kind === 'port' ? '#8a8f95' : '#4a4556'; g.fillRect(0, 0, 128, 64);
        g.fillStyle = d.kind === 'port' ? '#f2c230' : '#2b2733';
        for (let x = -64; x < 128; x += 32) { g.beginPath(); g.moveTo(x, 64); g.lineTo(x + 16, 64); g.lineTo(x + 48, 30); g.lineTo(x + 32, 30); g.fill(); }
        g.fillStyle = 'rgba(0,0,0,0.35)'; g.fillRect(0, 0, 128, 6);
      }
    }, true);
    const wallMat = new THREE.MeshLambertMaterial({ map: wallTex, side: THREE.DoubleSide, color: lin(d.wall) });
    const wh = d.kind === 'touge' ? 0.9 : 1.1;
    [-1, 1].forEach((s, k) => {
      const geo = ribbon(N, i => this.edge(i, s * w, 0), i => this.edge(i, s * w, wh), 4);
      // ribbon pone u en el ancho: lo intercambiamos para que la textura corra a lo largo
      const uv = geo.getAttribute('uv') as THREE.BufferAttribute;
      for (let j = 0; j < uv.count; j++) { const u = uv.getX(j), v = uv.getY(j); uv.setXY(j, v, u); }
      this.group.add(new THREE.Mesh(geo, wallMat));
      const neon = new THREE.Mesh(ribbon(N, i => this.edge(i, s * w, wh), i => this.edge(i, s * w, wh + 0.12), 4),
        new THREE.MeshBasicMaterial({ color: lin(d.neon[k]), side: THREE.DoubleSide }));
      this.group.add(neon);
    });

    // Línea de salida + pórtico
    const check = canvasTexture(128, 32, g => {
      for (let x = 0; x < 16; x++) for (let y = 0; y < 4; y++) { g.fillStyle = (x + y) % 2 ? '#111' : '#f4f4f4'; g.fillRect(x * 8, y * 8, 8, 8); }
    });
    const line = new THREE.Mesh(new THREE.PlaneGeometry(d.width, 2.4), new THREE.MeshLambertMaterial({ map: check }));
    line.rotation.x = -Math.PI / 2; line.position.copy(this.pts[0]).setY(0.02);
    line.rotation.z = Math.atan2(this.tan[0].x, this.tan[0].z);
    this.group.add(line);
    const gantry = new THREE.Group();
    const steel = new THREE.MeshLambertMaterial({ color: lin('#1c1b24') });
    [-1, 1].forEach(s => { const p = new THREE.Mesh(new THREE.BoxGeometry(0.6, 7, 0.6), steel); p.position.set(s * (w + 0.5), 3.5, 0); gantry.add(p); });
    const sign = canvasTexture(512, 64, g => {
      g.fillStyle = '#07050d'; g.fillRect(0, 0, 512, 64);
      g.font = 'italic 900 44px Arial, sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle';
      g.shadowColor = d.neon[0]; g.shadowBlur = 16; g.fillStyle = d.neon[0]; g.fillText('DRIFT  KINGS', 256, 34);
      g.shadowBlur = 0; g.fillStyle = '#fff'; g.fillText('DRIFT  KINGS', 256, 34);
    });
    const beam = new THREE.Mesh(new THREE.BoxGeometry((w + 0.5) * 2 + 0.6, 1.6, 0.5),
      [steel, steel, steel, steel, new THREE.MeshBasicMaterial({ map: sign }), new THREE.MeshBasicMaterial({ map: sign })]);
    beam.position.y = 7.4; gantry.add(beam);
    gantry.position.copy(this.pts[0]); gantry.rotation.y = Math.atan2(this.tan[0].x, this.tan[0].z);
    this.group.add(gantry);
  }

  /** Punto más cercano (búsqueda local alrededor de hint; global si hint < 0). */
  query(p: THREE.Vector3, hint = -1): TrackHit {
    const N = this.pts.length;
    let best = 0, bd = Infinity;
    const from = hint < 0 ? 0 : hint - 25, to = hint < 0 ? N : hint + 25;
    for (let j = from; j < to; j++) {
      const i = ((j % N) + N) % N, q = this.pts[i];
      const dd = (q.x - p.x) ** 2 + (q.z - p.z) ** 2;
      if (dd < bd) { bd = dd; best = i; }
    }
    const h = this.hit, q = this.pts[best];
    h.idx = best; h.tangent.copy(this.tan[best]); h.right.copy(this.right[best]);
    const dx = p.x - q.x, dz = p.z - q.z;
    h.lateral = dx * h.right.x + dz * h.right.z;
    h.along = best * SEG + dx * h.tangent.x + dz * h.tangent.z;
    return h;
  }

  /** Posición y tangente a una distancia d (con vuelta) y desplazamiento lateral. */
  at(d: number, lateral = 0, out = new THREE.Vector3(), tanOut?: THREE.Vector3) {
    const N = this.pts.length, f = (((d / SEG) % N) + N) % N, i = Math.floor(f), t = f - i, j = (i + 1) % N;
    out.lerpVectors(this.pts[i], this.pts[j], t);
    out.x += (this.right[i].x * (1 - t) + this.right[j].x * t) * lateral;
    out.z += (this.right[i].z * (1 - t) + this.right[j].z * t) * lateral;
    if (tanOut) tanOut.lerpVectors(this.tan[i], this.tan[j], t).normalize();
    return out;
  }

  /** Índices de las curvas más cerradas (vértices), separadas entre sí. */
  corners(minGap = 30) {
    const N = this.pts.length, order = [...Array(N).keys()].sort((a, b) => Math.abs(this.curv[b]) - Math.abs(this.curv[a]));
    const out: number[] = [];
    for (const i of order) {
      if (Math.abs(this.curv[i]) < 0.025) break;
      if (out.every(o => Math.min(Math.abs(o - i), N - Math.abs(o - i)) > minGap)) out.push(i);
    }
    return out;
  }

  dispose() { /* se libera con disposeTree del mundo */ }
}

