  text-shadow: 0 0 6px #ff2a6d, 0 0 18px #ff2a6d, 0 0 42px rgba(255, 42, 109, 0.7), 4px 4px 0 #2a0a3a;
}
.dk-title-cyan { color: #e9fdff; text-shadow: 0 0 6px #05d9e8, 0 0 18px #05d9e8, 0 0 40px rgba(5, 217, 232, 0.7), 4px 4px 0 #0a1a3a; }

