.dk-chip:hover { background: rgba(255, 255, 255, 0.1); }
.dk-chip-on { border-color: #ff2a6d; background: rgba(255, 42, 109, 0.18); box-shadow: 0 0 0 1px #ff2a6d, 0 0 18px rgba(255, 42, 109, 0.45); }

.dk-btn {
  font-family: Impact, 'Arial Black', Arial, sans-serif; font-style: italic; text-transform: uppercase; letter-spacing: 0.06em;
  background: linear-gradient(90deg, #ff2a6d, #ff6a3d); color: #fff; border-radius: 10px; transform: skewX(-8deg);
