@keyframes dk-toast { 0% { transform: translateY(16px) scale(0.7); opacity: 0; } 14% { transform: translateY(0) scale(1.08); opacity: 1; } 24% { transform: scale(1); } 80% { opacity: 1; } 100% { transform: translateY(-22px); opacity: 0; } }
